#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release the line if it's still allocated
    if (line != NULL) {
        gpiod_line_release(line);
    }

    // Close the chip if it's still open
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int value;
    int ret;

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'.\n", GPIO_CHIP);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d.\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line for output: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the value from standard input
        printf("Enter 0 or 1: ");
        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "Error: Invalid input. Please enter 0 or 1.\n");
            while (getchar() != '\n'); // Clear input buffer
            continue;
        }

        // Validate the input
        if (value != 0 && value != 1) {
            fprintf(stderr, "Error: Invalid value. Must be 0 or 1.\n");
            continue;
        }

        // Set the GPIO line value
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line value: %d\n", ret);
            break; // Exit loop on error
        }

        // Print the applied value
        printf("Applied value: %d\n", value);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// Define ADS1115 registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting gracefully...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read the conversion register
int16_t read_conversion(int fd) {
    uint8_t msb, lsb;

    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION, &msb) != 0) {
        fprintf(stderr, "Error reading MSB\n");
        return -1;
    }

    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION + 1, &lsb) != 0) {
        fprintf(stderr, "Error reading LSB\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t result = (int16_t)((msb << 8) | lsb);

    return result;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure the ADS1115 for single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint8_t config = 0x43; // Single-shot, AIN0, +/-4.096V, 128 SPS
    config |= (0x02 << 11); // Start single conversion
    config |= (0x00 << 9); // Disable comparator
    config |= (0x00 << 5); // Disable comparator
    config |= (0x00 << 2); // Disable comparator
    config |= (0x00 << 0); // Disable comparator

    if (i2c_write_reg(i2c_fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Error writing configuration\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        int16_t raw_value = read_conversion(i2c_fd);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading conversion data\n");
            continue; // Try again
        }

        // Print the raw value
        printf("%d\n", raw_value);

        // Wait 0.5 seconds
        sleep(0.5);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define TOBJ1_REG 0x07

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from MLX90614
float read_temperature() {
    char buf[2];
    int raw_temp;
    float temp_celsius;

    // Read two bytes from register TOBJ1
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1000.0; // Indicate error with a very low temperature
    }

    // Combine the two bytes into a 16-bit value
    raw_temp = (buf[0] << 8) | buf[1];

    // Convert raw temperature to Celsius (see MLX90614 datasheet)
    temp_celsius = (raw_temp * 0.02) - 273.15;

    return temp_celsius;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in 5 seconds.\n");
        }

        sleep(5);
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
