#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17

static struct gpiod_chip *chip;
static struct gpiod_line *line4, *line17;

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line4 != NULL) {
        gpiod_line_release(line4);
    }
    if (line17 != NULL) {
        gpiod_line_release(line17);
    }

    // Close the chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get the GPIO line for GPIO 4
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        fprintf(stderr, "Error getting GPIO line 4\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the GPIO line for GPIO 17
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line 17\n");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(line4, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 4 as output\n");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line17, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 17 as output\n");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 4 high
        if (set_gpio_value(line4, 1) == 0) {
            printf("GPIO 4: HIGH\n");
        } else {
            fprintf(stderr, "Failed to set GPIO 4 HIGH\n");
        }

        // Set GPIO 17 low
        if (set_gpio_value(line17, 0) == 0) {
            printf("GPIO 17: LOW\n");
        } else {
            fprintf(stderr, "Failed to set GPIO 17 LOW\n");
        }

        sleep(1);
    }

    return 0; // This will never be reached due to the infinite loop, but it's good practice
}

