#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout
#define MAX_DISTANCE 400      // Maximum measurable distance in cm

// Global variables
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int setup_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(config->trigger_pin, 0);
    gpioDelay(1000); // 1ms delay

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the duration of the echo pulse
long get_pulse_duration() {
    long start_tick, end_tick, diff;

    // Wait for echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration <= 0) {
        return -1.0; // Invalid pulse duration
    }

    float time_taken = (float)pulse_duration / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;   // Distance = (Time * Speed of Sound) / 2

    // Validate distance
    if (distance > MAX_DISTANCE) {
        return -1.0; // Distance out of range
    }

    return distance;
}

// Function to report the distance
void report_distance(float distance) {
    if (distance >= 0) {
        printf("Distance: %.2f cm\n", distance);
    } else {
        fprintf(stderr, "Error: Invalid distance measurement\n");
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    fprintf(stderr, "GPIO terminated.\n");
}

int main() {
    gpio_config_t config = {TRIGGER_PIN, ECHO_PIN};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio(&config) != 0) {
        return 1;
    }

    fprintf(stderr, "HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_duration = get_pulse_duration();

        if (pulse_duration > 0) {
            float distance = calculate_distance(pulse_duration);
            report_distance(distance);
        } else {
            fprintf(stderr, "Error: No echo received or timeout occurred\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// Define ADS1115 registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_6_144V 0x0000   // +/-6.144V range = Gain 2
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int fd, uint8_t reg) {
    int16_t value;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, &value, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    return __builtin_bswap16(value); // Byte swap for correct endianness
}

// Function to write a 16-bit value to the I2C device
int write_i2c_word(int fd, uint8_t reg, uint16_t value) {
    uint16_t swapped_value = __builtin_bswap16(value);
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (write(fd, &swapped_value, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to initialize the ADS1115
int init_ads1115(int fd) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_6_144V |
                      CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD |
                      CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    if (write_i2c_word(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Error initializing ADS1115\n");
        return -1;
    }
    return 0;
}

// Function to read the ADC value
int16_t read_adc(int fd) {
    // Read the conversion register
    int16_t adc_value = read_i2c_word(fd, ADS1115_REG_CONVERSION);
    if (adc_value == -1) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    // Check for valid ADC reading
    if (adc_value >= 32768 && adc_value <= 65535) {
        return adc_value;
    } else {
        fprintf(stderr, "Invalid ADC reading: %d\n", adc_value);
        return -1;
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the ADS1115
    if (init_ads1115(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        int16_t adc_value = read_adc(i2c_fd);
        if (adc_value != -1) {
            // Print the ADC value
            printf("%d\n", adc_value);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // This point should not be reached due to the infinite loop
    close(i2c_fd);
    return 0;
}

