#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// Define ADS1115 registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read the conversion register
int16_t read_conversion(int fd) {
    uint8_t msb, lsb;

    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION, &msb) != 0) {
        fprintf(stderr, "Error reading MSB\n");
        return -1;
    }

    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION + 1, &lsb) != 0) {
        fprintf(stderr, "Error reading LSB\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t result = (int16_t)((msb << 8) | lsb);
    return result;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure the ADS1115 for single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint8_t config = 0x43; // Single-shot, AIN0, +/-4.096V, 128 SPS
    config |= (0x02 << 11); // Start single conversion
    config |= (0x00 << 9); // Disable comparator
    config |= (0x00 << 5); // Disable comparator
    config |= (0x00 << 2); // Disable comparator
    config |= (0x00 << 0); // Disable comparator

    if (i2c_write_reg(i2c_fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Error writing configuration\n");
        close(i2c_fd);
        return 1;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    int16_t conversion_value = read_conversion(i2c_fd);
    if (conversion_value == -1) {
        fprintf(stderr, "Error reading conversion value\n");
        close(i2c_fd);
        return 1;
    }

    // Print the conversion value
    printf("Conversion Value: %d\n", conversion_value);

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

