void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO pin
int setup_gpio(int gpio_pin) {
    int ret;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line
    line_4 = gpiod_chip_get_line(chip, GPIO_4);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_22 = gpiod_chip_get_line(chip, GPIO_22);
    line_27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line_4 || !line_17 || !line_22 || !line_27) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "example";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line_4, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 4");
        gpiod_chip_close(chip);
        return -1;
    }
    ret = gpiod_line_request(line_17, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17");
        gpiod_chip_close(chip);
        return -1;
    }
    ret = gpiod_line_request(line_22, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 22");
        gpiod_chip_close(chip);
        return -1;
    }
    ret = gpiod_line_request(line_27, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 27");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio(void) {
    int ret;

    // Set all lines to low
    ret = gpiod_line_set_value(line_4, 0);
    if (ret < 0) perror("Error setting GPIO 4 value");
    ret = gpiod_line_set_value(line_17, 0);
    if (ret < 0) perror("Error setting GPIO 17 value");
    ret = gpiod_line_set_value(line_22, 0);
    if (ret < 0) perror("Error setting GPIO 22 value");
    ret = gpiod_line_set_value(line_27, 0);
    if (ret < 0) perror("Error setting GPIO 27 value");

    // Release lines
    gpiod_line_release(line_4);
    gpiod_line_release(line_17);
    gpiod_line_release(line_22);
    gpiod_line_release(line_27);

    // Close chip
    gpiod_chip_close(chip);
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (setup_gpio(GPIO_4) != 0 ||
        setup_gpio(GPIO_17) != 0 ||
        setup_gpio(GPIO_22) != 0 ||
        setup_gpio(GPIO_27) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read current values
        ret = gpiod_line_get_value(line_4);
        if (ret < 0) perror("Error reading GPIO 4 value");
        ret = gpiod_line_get_value(line_17);
        if (ret < 0) perror("Error reading GPIO 17 value");
        ret = gpiod_line_get_value(line_22);
        if (ret < 0) perror("Error reading GPIO 22 value");
        ret = gpiod_line_get_value(line_27);
        if (ret < 0) perror("Error reading GPIO 27 value");

