               ret, gpiod_line_get_value(line_17), gpiod_line_get_value(line_22), gpiod_line_get_value(line_27));

        // Toggle values every 2 seconds
        sleep(2);
    }

    return 0; // This will never be reached due to the infinite loop, but it's good practice to include it.
}

