#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define HUMID_CMD 0xE5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read temperature from SI7021
float read_temperature() {
    int raw_temp;
    float temperature;

    // Send temperature measurement command
    if (i2cWriteByte(i2c_handle, TEMP_CMD) != 0) {
        fprintf(stderr, "Error writing temperature command.\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement (typical conversion time is 11ms)
    gpioDelay(20);

    // Read two bytes of temperature data
    raw_temp = i2cReadWordData(i2c_handle, 0);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data.\n");
        return -1000.0; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Validate temperature range
    if (temperature < -40.0 || temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        return -1000.0; // Indicate invalid reading
    }

    return temperature;
}

// Function to read humidity from SI7021
float read_humidity() {
    int raw_humidity;
    float humidity;

    // Send humidity measurement command
    if (i2cWriteByte(i2c_handle, HUMID_CMD) != 0) {
        fprintf(stderr, "Error writing humidity command.\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement (typical conversion time is 11ms)
    gpioDelay(20);

    // Read two bytes of humidity data
    raw_humidity = i2cReadWordData(i2c_handle, 0);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data.\n");
        return -1000.0; // Indicate error
    }

    // Convert raw humidity to relative humidity
    humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    // Validate humidity range
    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", humidity);
        return -1000.0; // Indicate invalid reading
    }

    return humidity;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature, humidity;

        // Read temperature
        temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Read humidity
        humidity = read_humidity();
        if (humidity > -999.0) { // Check for valid reading
            printf("Humidity: %.2f %%\n", humidity);
        } else {
            fprintf(stderr, "Failed to read humidity.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

