}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int fd) {
    uint8_t buf[2];
    int16_t value;

    // Read two bytes from the conversion register
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1; // Indicate error
    }

    // Combine the bytes into a 16-bit value
    value = (buf[0] << 8) | buf[1];

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1; // Exit with error
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1; // Exit with error
    }

    // Configure the ADS1115 for single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint8_t config[3];
    config[0] = CONFIG_REG; // Configuration register address
    config[1] = 0xC3;       // MSB: 11000011 (Single-shot, AIN0, +/-4.096V, 128 SPS)
    config[2] = 0x83;       // LSB: 10000011 (Disable comparator, start single conversion)

    // Write the configuration to the ADS1115
    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1; // Exit with error
    }

    // Delay for conversion (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    int16_t reading = read_ads1115(i2c_fd);
    if (reading == -1) {
        fprintf(stderr, "Error reading ADS1115, exiting.\n");
        close(i2c_fd);
        return 1; // Exit with error
    }

    // Print the reading
    printf("ADS1115 Reading: %d\n", reading);

    // Close the I2C bus
    close(i2c_fd);

    return 0;
}

