// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_LINES];
} gpio_context_t;

gpio_context_t context;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++) {
        if (context.lines[i] != NULL) {
            gpiod_line_release(context.lines[i]);
        }
    }

    // Close GPIO chip
    if (context.chip != NULL) {
        gpiod_chip_close(context.chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    int ret = 0;

    // Open GPIO chip
    context.chip = gpiod_chip_open_by_name("gpiochip0");
    if (!context.chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    for (int i = 0; i < NUM_LINES; i++) {
        context.lines[i] = gpiod_chip_get_line(context.chip, gpio_pins[i]);
        if (!context.lines[i]) {
            perror("Error getting GPIO line");
            ret = -1;
            break;
        }

        // Request GPIO line as output
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "example";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        ret = gpiod_line_request(context.lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting GPIO line as output");
            ret = -1;
            break;
        }
    }

    return ret;
}

// Function to set GPIO output value
void set_gpio_output(int pin_index, int value) {
    if (pin_index < 0 || pin_index >= NUM_LINES) {
        fprintf(stderr, "Invalid GPIO pin index: %d\n", pin_index);
        return;
    }

    int ret = gpiod_line_set_value(context.lines[pin_index], value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
    }
}

// Function to report current GPIO states
void report_gpio_states() {
    for (int i = 0; i < NUM_LINES; i++) {
        int value = gpiod_line_get_value(context.lines[i]);
        if (value < 0) {
            perror("Error getting GPIO line value");
            continue; // Continue to the next pin, even if one fails
        }
        printf("GPIO%d: %d ", gpio_pins[i], value);
    }
    printf("\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    for (int i = 0; i < 256; i++) {
        // Set GPIO outputs in sequence
        for (int j = 0; j < NUM_LINES; j++) {
            set_gpio_output(j, 1);
            report_gpio_states();
            usleep(100000); // 100ms delay
            set_gpio_output(j, 0);
            report_gpio_states();
            usleep(100000); // 100ms delay
        }
    }

    // Cleanup (should not reach here normally due to signal handler)
    signal_handler(SIGINT);

    return 0;
}

