#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int fd;
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;

    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the serial port
    fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        fprintf(stderr, "Error opening %s: %s\n", UART_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    // Configure the serial port
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        fprintf(stderr, "Error getting attributes of %s: %s\n", UART_DEVICE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;   // Read at least 0 characters
    tty.c_cc[VTIME] = 5;  // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        fprintf(stderr, "Error setting attributes of %s: %s\n", UART_DEVICE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Reading from %s at %d baud...\n", UART_DEVICE, B115200);

    while (keep_running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("%s", buffer);
        } else if (bytes_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("read");
            fprintf(stderr, "Error reading from %s: %s\n", UART_DEVICE, strerror(errno));
            break;
        } else {
            usleep(10000); // Sleep for 10ms to avoid busy-waiting
        }
    }

    // Cleanup
    close(fd);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

