#include <unistd.h>

#define DHT11_PIN 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int read_dht11_data(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int i, j;

    gpioSetMode(DHT11_PIN, PI_OUTPUT);
    gpioWrite(DHT11_PIN, 0);
    gpioDelay(1);
    gpioWrite(DHT11_PIN, 1);
    gpioDelay(30);

    gpioSetMode(DHT11_PIN, PI_INPUT);

    unsigned int start_time = gpioTick();
    while (gpioRead(DHT11_PIN) == 1) {
        if (gpioTick() - start_time > 200) return -1; // Timeout
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_PIN) == 0) {
        if (gpioTick() - start_time > 200) return -1; // Timeout
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_PIN) == 1) {
        if (gpioTick() - start_time > 200) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        start_time = gpioTick();
        while (gpioRead(DHT11_PIN) == 0) {
            if (gpioTick() - start_time > 200) return -1; // Timeout
        }

        start_time = gpioTick();
        while (gpioRead(DHT11_PIN) == 1) {
            if (gpioTick() - start_time > 200) return -1; // Timeout
        }

        if ((gpioTick() - start_time) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1; // Checksum failure
    }

    *humidity = (float)data[0];
    *temperature = (float)data[2];

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht11_data(&temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT11 read failed with error code: %d\n", result);
            gpioTerminate();
            return 1;
        }

        sleep(5);
    }

    gpioTerminate();
    return 0;
}

