void cleanup_gpio(gpio_line_t *lines);

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (init_gpio(&gpio_lines[0], GPIO_4) != 0 ||
        init_gpio(&gpio_lines[1], GPIO_17) != 0 ||
        init_gpio(&gpio_lines[2], GPIO_18) != 0 ||
        init_gpio(&gpio_lines[3], GPIO_22) != 0 ||
        init_gpio(&gpio_lines[4], GPIO_27) != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines. Exiting.\n");
        cleanup_gpio(gpio_lines);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO values in sequence
        set_gpio_value(&gpio_lines[0], 1);
        printf("GPIO %d: HIGH\n", GPIO_4);
        usleep(50000); // 0.05 seconds

        set_gpio_value(&gpio_lines[1], 1);
        printf("GPIO %d: HIGH\n", GPIO_17);
        usleep(50000);

        set_gpio_value(&gpio_lines[2], 1);
        printf("GPIO %d: HIGH\n", GPIO_18);
        usleep(50000);

        set_gpio_value(&gpio_lines[3], 1);
        printf("GPIO %d: HIGH\n", GPIO_22);
        usleep(50000);

        set_gpio_value(&gpio_lines[4], 1);
        printf("GPIO %d: HIGH\n", GPIO_27);
        usleep(50000);

        // Reset GPIO values in reverse order
        set_gpio_value(&gpio_lines[4], 0);
        printf("GPIO %d: LOW\n", GPIO_27);
        usleep(50000);

        set_gpio_value(&gpio_lines[3], 0);
        printf("GPIO %d: LOW\n", GPIO_22);
        usleep(50000);

        set_gpio_value(&gpio_lines[2], 0);
        printf("GPIO %d: LOW\n", GPIO_18);
        usleep(50000);

        set_gpio_value(&gpio_lines[1], 0);
        printf("GPIO %d: LOW\n", GPIO_17);
        usleep(50000);

        set_gpio_value(&gpio_lines[0], 0);
        printf("GPIO %d: LOW\n", GPIO_4);
        usleep(50000);
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d. Cleaning up and exiting.\n", sig);
    cleanup_gpio(gpio_lines);
    exit(0);
}

// Function to initialize a GPIO line
int init_gpio(gpio_line_t *line, int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    line->chip = chip;

    struct gpiod_line *l = gpiod_chip_get_line(chip, pin);
    if (!l) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    line->line = l;

    int ret = gpiod_line_request_output(l, "myapp", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
void set_gpio_value(gpio_line_t *line, int value) {
    int ret = gpiod_line_set_value(line->line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
    }
}

// Function to cleanup GPIO lines
void cleanup_gpio(gpio_line_t *lines) {
    for (int i = 0; i < 5; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
        if (lines[i].chip) {
            gpiod_chip_close(lines[i].chip);
        }
    }
}

