#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins (BCM numbering)
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_7 7
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_17 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *lines[9];
int running = 1;

// Function prototypes
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;

    // Release lines
    for (int i = 0; i < 9; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int i;
    struct gpiod_line_request_config config;
    struct gpiod_line *line;
    int value;

    // Register signal handler
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIOCHIP);
        return 1;
    }

    // Request lines
    for (i = 0; i < 9; i++) {
        line = gpiod_chip_get_line(chip, i);
        if (!line) {
            fprintf(stderr, "Error: Could not get line %d\n", i);
            goto cleanup_and_exit;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "example";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(line, &config, 0) < 0) {
            fprintf(stderr, "Error: Could not request line %d as output\n", i);
            goto cleanup_and_exit;
        }

        lines[i] = line;
    }

    // Main loop
    while (running) {
        for (i = 0; i < 9; i++) {
            value = (i + 1) % 2; // Toggle between 0 and 1
            if (gpiod_line_set_value(lines[i], value) < 0) {
                fprintf(stderr, "Error: Could not set value for line %d\n", i);
                goto cleanup_and_exit;
            }
            printf("GPIO%d: %d\n", i + 2, value);
        }
        usleep(50000); // 0.05 seconds
    }

cleanup_and_exit:
    // Cleanup in case of error
    for (i = 0; i < 9; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return 1;
}

