#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

int i2c_fd = -1;

void cleanup(int signal) {
    printf("Cleaning up and exiting.\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int ret;
    uint8_t buf[2];
    uint16_t raw_result;
    float exponent, result;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read configuration register
    buf[0] = CONFIG_REG;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        perror("Error writing to config register");
        close(i2c_fd);
        return 1;
    }

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Error reading config register");
        close(i2c_fd);
        return 1;
    }

    // Extract exponent and result
    raw_result = (buf[0] << 8) | buf[1];

    exponent = (raw_result >> 12) & 0x0F;
    result = (raw_result & 0x0FFF) * (0.00625 * (1 << exponent));

    printf("Temperature: %.2f °C\n", result);

    // Cleanup
    close(i2c_fd);

    return 0;
}

