static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_2 = NULL;
static struct gpiod_line *line_3 = NULL;

// Function to export a GPIO line
struct gpiod_line *export_gpio(int gpio_num) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_num);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", gpio_num);
        return NULL;
    }

    int ret = gpiod_line_request_output(line, "example", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %d\n", gpio_num, ret);
        gpiod_line_release(line);
        return NULL;
    }
    return line;
}

// Function to unexport a GPIO line
void unexport_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

// Function to set the GPIO value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value %d on line: %d\n", value, ret);
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Unexport GPIO lines
    unexport_gpio(line_2);
    unexport_gpio(line_3);

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Export GPIO lines
    line_2 = export_gpio(GPIO_2);
    line_3 = export_gpio(GPIO_3);

    if (!line_2 || !line_3) {
        // If either line failed to export, clean up what was exported so far
        if (line_2) unexport_gpio(line_2);
        if (line_3) unexport_gpio(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 high
        if (set_gpio_value(line_2, 1) != 0) {
            fprintf(stderr, "Error setting GPIO 2 high, exiting.\n");
            break;
        }
        printf("GPIO 2: HIGH\n");

        // Set GPIO 3 low
        if (set_gpio_value(line_3, 0) != 0) {
            fprintf(stderr, "Error setting GPIO 3 low, exiting.\n");
            break;
        }
        printf("GPIO 3: LOW\n");

        // Wait 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up
    unexport_gpio(line_2);
    unexport_gpio(line_3);
    gpiod_chip_close(chip);

    return 0;
}

