#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle
        gpioPWM(PWM_PIN_3, 192); // 75% duty cycle

        // Print current PWM settings
        printf("PWM_PIN_1: 50%%, PWM_PIN_2: 25%%, PWM_PIN_3: 75%%\n");

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Release GPIO pins and terminate pigpio library
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

