#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>

#define MAX_SENSORS 3
#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"

// Structure to hold sensor information
typedef struct {
    char id[20];
    int fd;
} sensor_t;

sensor_t sensors[MAX_SENSORS];
int num_sensors = 0;

// Function prototypes
int read_temperature(const char *sensor_id, float *temperature);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    printf("\nCaught signal %d, exiting...\n", signum);
    // Close file descriptors
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].fd != -1) {
            close(sensors[i].fd);
        }
    }
    exit(0);
}

// Function to read temperature from a single sensor
int read_temperature(const char *sensor_id, float *temperature) {
    char path[100];
    snprintf(path, sizeof(path), "%s%s/%s", W1_DEVICES_DIR, sensor_id, W1_SLAVE_FILE);

    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read == -1) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';

    // Check for CRC error
    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC error in sensor %s\n", sensor_id);
        close(fd);
        return -1;
    }

    // Extract temperature
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in sensor %s\n", sensor_id);
        close(fd);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    close(fd);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Find all DS18B20 devices
    DIR *dir;
    struct dirent *ent;
    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Could not open devices directory");
        return 1;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            if (num_sensors < MAX_SENSORS) {
                strncpy(sensors[num_sensors].id, ent->d_name, sizeof(sensors[num_sensors].id) - 1);
                sensors[num_sensors].id[sizeof(sensors[num_sensors].id) - 1] = '\0'; // Ensure null termination
                sensors[num_sensors].fd = -1; // Initialize file descriptor
                num_sensors++;
            } else {
                fprintf(stderr, "Too many sensors found, ignoring %s\n", ent->d_name);
            }
        }
    }
    closedir(dir);

    if (num_sensors == 0) {
        fprintf(stderr, "No DS18B20 sensors found!\n");
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < num_sensors; i++) {
            float temperature;
            if (read_temperature(sensors[i].id, &temperature) == 0) {
                printf("Sensor %s: %.2f °C\n", sensors[i].id, temperature);
            } else {
                fprintf(stderr, "Failed to read temperature from sensor %s\n", sensors[i].id);
            }
        }
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define HTU21D_ADDR 0x40

// Function prototypes
int read_htu21d(uint8_t reg, uint16_t *data);
uint8_t crc8(const uint8_t *data, int len);
void signal_handler(int signal);

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from HTU21D
int read_htu21d(uint8_t reg, uint16_t *data) {
    char buf[3];
    int result;

    // Send the measurement command
    result = i2cWriteByteData(i2c_handle, reg, 0x00); // No hold master mode
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 50ms)
    gpioDelay(70000); // 70ms

    // Read three bytes from the device
    result = i2cReadI2CBlockData(i2c_handle, reg, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two data bytes into a 16-bit value
    *data = (buf[0] << 8) | buf[1];

    // CRC check
    uint8_t crc = buf[2];
    uint8_t data_to_check[2] = {buf[0], buf[1]};
    if (crc8(data_to_check, 2) != crc) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read temperature
        if (read_htu21d(0xE3, &raw_temperature) == 0) {
            // Convert raw temperature to Celsius
            temperature = -46.85 + 175.72 * ((float)raw_temperature / 65536.0);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        // Read humidity
        if (read_htu21d(0xE5, &raw_humidity) == 0) {
            // Convert raw humidity to relative humidity
            humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);
            if (humidity < 0.0) humidity = 0.0;
            if (humidity > 100.0) humidity = 100.0;
            printf("Humidity: %.2f %%\n", humidity);
        } else {
            fprintf(stderr, "Failed to read humidity.\n");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup (should not reach here under normal circumstances due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

