#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3;

// Function prototypes
int setup_gpio(int gpio_num);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO pin
int setup_gpio(int gpio_num) {
    struct gpiod_line_request_config config;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line_2 || !line_3) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "example-app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line_2, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 2");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(line_3, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 3");
        gpiod_chip_close(chip);
        return -1;
    }

