#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the ADXL345
int adxl345_init() {
    // Set data format: +/- 2g range, full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x08) < 0) { //0x08 sets full resolution
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;

    // Main loop
    while (1) {
        if (read_acceleration(&x, &y, &z) == 0) {
            printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }
        usleep(100000); // 0.1 seconds
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

