// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17 != NULL) {
        gpiod_line_release(line_17);
    }
    if (line_18 != NULL) {
        gpiod_line_release(line_18);
    }

    // Close the chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get the GPIO line for GPIO 17
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        fprintf(stderr, "Error getting GPIO line 17\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the GPIO line for GPIO 18
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        fprintf(stderr, "Error getting GPIO line 18\n");
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(line_17, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line 17 as output\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_18, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line 18 as output\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 17 high
    if (set_gpio_value(line_17, 1) == 0) {
        printf("GPIO 17 set to HIGH\n");
    } else {
        fprintf(stderr, "Failed to set GPIO 17 to HIGH\n");
    }

    // Set GPIO 18 low
    if (set_gpio_value(line_18, 0) == 0) {
        printf("GPIO 18 set to LOW\n");
    } else {
        fprintf(stderr, "Failed to set GPIO 18 to LOW\n");
    }

    // Clean up and exit
    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for DHT22 sensors
#define DHT22_GPIO_1 17
#define DHT22_GPIO_2 22
#define DHT22_GPIO_3 23
#define DHT22_GPIO_4 24

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} SensorData;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read data from a DHT22 sensor
SensorData read_dht22(int gpio_pin) {
    SensorData data = {0.0, 0.0, 0};
    int i, j;
    int data_bits[40];
    int bit_count = 0;
    unsigned int pulse_lengths[80];
    int pulse_index = 0;

    // Send start signal
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0);
    gpioDelay(1);
    gpioWrite(gpio_pin, 1);
    gpioDelay(30); // Changed delay to 30 microseconds

    gpioSetMode(gpio_pin, PI_INPUT);

    // Read response (ignore first 3 pulses)
    for (i = 0; i < 40; i++) {
        while (gpioRead(gpio_pin) == 0 && pulse_index < 80); // Wait for high
        while (gpioRead(gpio_pin) == 1 && pulse_index < 80); // Wait for low
        pulse_lengths[pulse_index++] = gpioTick();
        while (gpioRead(gpio_pin) == 0 && pulse_index < 80); // Wait for high
        while (gpioRead(gpio_pin) == 1 && pulse_index < 80); // Wait for low
        pulse_lengths[pulse_index++] = gpioTick();
    }

    // Decode data bits
    for (i = 0; i < 40; i++) {
        if (pulse_lengths[2 * i + 1] - pulse_lengths[2 * i] > 50) {
            data_bits[i] = 1;
        } else {
            data_bits[i] = 0;
        }
    }

    // Convert bits to bytes
    unsigned char data_bytes[5] = {0};
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            data_bytes[i] <<= 1;
            data_bytes[i] |= data_bits[i * 8 + j];
        }
    }

    // Validate checksum
    if ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) != data_bytes[4]) {
        fprintf(stderr, "Checksum error on GPIO %d\n", gpio_pin);
        return data; // Return invalid data
    }

    // Calculate temperature and humidity
    data.humidity = (float)((data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data.temperature = (float)(((data_bytes[2] & 0x7F) << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
        data.temperature *= -1.0;
    }

    data.valid = 1; // Mark as valid

    return data;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        SensorData sensor1_data = read_dht22(DHT22_GPIO_1);
        SensorData sensor2_data = read_dht22(DHT22_GPIO_2);
        SensorData sensor3_data = read_dht22(DHT22_GPIO_3);
        SensorData sensor4_data = read_dht22(DHT22_GPIO_4);

        // Print sensor data
        printf("GPIO %d: Temp=%.1fC, Humidity=%.1f%%, Valid=%d\n", DHT22_GPIO_1, sensor1_data.temperature, sensor1_data.humidity, sensor1_data.valid);
        printf("GPIO %d: Temp=%.1fC, Humidity=%.1f%%, Valid=%d\n", DHT22_GPIO_2, sensor2_data.temperature, sensor2_data.humidity, sensor2_data.valid);
        printf("GPIO %d: Temp=%.1fC, Humidity=%.1f%%, Valid=%d\n", DHT22_GPIO_3, sensor3_data.temperature, sensor3_data.humidity, sensor3_data.valid);
        printf("GPIO %d: Temp=%.1fC, Humidity=%.1f%%, Valid=%d\n", DHT22_GPIO_4, sensor4_data.temperature, sensor4_data.humidity, sensor4_data.valid);

        // Wait for 2 seconds
        sleep(2);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    int duty_cycle_1, duty_cycle_2, duty_cycle_3;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read user input
        printf("Enter duty cycle for GPIO %d (0-100): ", PWM_PIN_1);
        result = scanf("%d", &duty_cycle_1);
        if (result != 1 || duty_cycle_1 < 0 || duty_cycle_1 > 100) {
            fprintf(stderr, "Invalid input for GPIO %d. Using default value 0.\n", PWM_PIN_1);
            duty_cycle_1 = 0;
        }
        while (getchar() != '\n'); // Clear input buffer

        printf("Enter duty cycle for GPIO %d (0-100): ", PWM_PIN_2);
        result = scanf("%d", &duty_cycle_2);
        if (result != 1 || duty_cycle_2 < 0 || duty_cycle_2 > 100) {
            fprintf(stderr, "Invalid input for GPIO %d. Using default value 0.\n", PWM_PIN_2);
            duty_cycle_2 = 0;
        }
        while (getchar() != '\n'); // Clear input buffer

        printf("Enter duty cycle for GPIO %d (0-100): ", PWM_PIN_3);
        result = scanf("%d", &duty_cycle_3);
        if (result != 1 || duty_cycle_3 < 0 || duty_cycle_3 > 100) {
            fprintf(stderr, "Invalid input for GPIO %d. Using default value 0.\n", PWM_PIN_3);
            duty_cycle_3 = 0;
        }
        while (getchar() != '\n'); // Clear input buffer

        // Apply duty cycles to PWM pins
        gpioPWM(PWM_PIN_1, duty_cycle_1 * 255 / 100);
        gpioPWM(PWM_PIN_2, duty_cycle_2 * 255 / 100);
        gpioPWM(PWM_PIN_3, duty_cycle_3 * 255 / 100);

        // Print current state
        printf("GPIO %d: %d%%, GPIO %d: %d%%, GPIO %d: %d%%\n", PWM_PIN_1, duty_cycle_1, PWM_PIN_2, duty_cycle_2, PWM_PIN_3, duty_cycle_3);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

    // Clean up and terminate
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

