#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable register values
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ENABLE_AIEN     (0x10) // RGBC Interrupt Enable

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the TCS34725
uint16_t tcs34725_read_word(uint8_t reg)
{
    int result = i2cReadWordData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return 0; // Return 0 on error
    }
    return (uint16_t)result;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init()
{
    // Enable power and RGBC conversion
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to enable register.\n");
        return -1;
    }

    // Set integration time (ATIME).  Atime determines the integration time.
    // Valid values are 2.4ms, 24ms, 58.4ms, 101ms, 154ms, 256ms, 512ms, 1024ms.
    // We'll use 101ms (0xEB).
    if (i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error writing to ATIME register.\n");
        return -1;
    }

    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t clear = tcs34725_read_word(TCS34725_CDATA);
        uint16_t red = tcs34725_read_word(TCS34725_RDATA);
        uint16_t green = tcs34725_read_word(TCS34725_GDATA);
        uint16_t blue = tcs34725_read_word(TCS34725_BDATA);

        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);

        gpioDelay(200); // Wait 0.2 seconds
    }

    // Cleanup (should not reach here in normal execution due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

