// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    ssd1306_clearDisplay(); // Clear the display before exiting
    close(i2c_fd);           // Close the I2C device
    exit(0);
}

// Sends a command to the SSD1306
void ssd1306_sendCommand(uint8_t command) {
    uint8_t buffer[2];
    buffer[0] = 0x00; // Control byte: command
    buffer[1] = command;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command");
    }
}

// Initializes the SSD1306
void ssd1306_init() {
    ssd1306_sendCommand(0xAE); // Display off
    ssd1306_sendCommand(0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_sendCommand(0x80); // --ratio
    ssd1306_sendCommand(0xA8); // Set multiplex ratio
    ssd1306_sendCommand(0x3F); // --ratio
    ssd1306_sendCommand(0xD3); // Set display offset
    ssd1306_sendCommand(0x00); // --offset
    ssd1306_sendCommand(0x40); // Set start line address
    ssd1306_sendCommand(0x8D); // Charge pump setting
    ssd1306_sendCommand(0x14); // --enable
    ssd1306_sendCommand(0x20); // Set memory addressing mode
    ssd1306_sendCommand(0x00); // --horizontal addressing mode
    ssd1306_sendCommand(0xA1); // Set segment re-map
    ssd1306_sendCommand(0xC8); // Set COM scan direction
    ssd1306_sendCommand(0xDA); // Set COM pins hardware configuration
    ssd1306_sendCommand(0x12); // --configuration
    ssd1306_sendCommand(0x81); // Set contrast control
    ssd1306_sendCommand(0xCF); // --contrast
    ssd1306_sendCommand(0xD9); // Set pre-charge period
    ssd1306_sendCommand(0xF1); // --period
    ssd1306_sendCommand(0xDB); // Set VCOMH deselect level
    ssd1306_sendCommand(0x40); // --level
    ssd1306_sendCommand(0xA4); // Entire display ON/OFF
    ssd1306_sendCommand(0xA6); // Set normal display
    ssd1306_sendCommand(0xAF); // Display on
}

// Clears the display buffer
void ssd1306_clearDisplay() {
    uint8_t buffer[1025]; // 1 page of data (128 pixels / 8 bits/pixel)
    memset(buffer, 0x00, sizeof(buffer));
    buffer[0] = 0x40; // Start at page 0
    if (write(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("Failed to clear display");
    }
}

// Displays a string at the specified coordinates
void ssd1306_displayString(int x, int y, const char *str) {
    ssd1306_setCursor(x, y);
    while (*str) {
        ssd1306_writeChar(*str++);
    }
}

// Sets the cursor position
void ssd1306_setCursor(int x, int y) {
    ssd1306_sendCommand(0xB0 + (y / 8));       // Set page start address for page address mode
    ssd1306_sendCommand(0x00 + (x & 0x0F));   // Set lower column start address
    ssd1306_sendCommand(0x10 + ((x >> 4) & 0x0F)); // Set higher column start address
}

