#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_2, *line_3, *line_5;

// Function prototypes
int setup_gpio(int gpio_num);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO function
int setup_gpio(int gpio_num) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", CHIP_NAME);
        return -1;
    }

    // Get GPIO line
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    switch (gpio_num) {
        case GPIO_2:
            line_2 = gpiod_chip_get_line(chip, GPIO_2);
            if (!line_2) {
                fprintf(stderr, "Error getting GPIO %d line\n", GPIO_2);
                gpiod_chip_close(chip);
                return -1;
            }
            ret = gpiod_line_request(line_2, &config, 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d line: %d\n", GPIO_2, ret);
                gpiod_chip_close(chip);
                return -1;
            }
            break;
        case GPIO_3:
            line_3 = gpiod_chip_get_line(chip, GPIO_3);
            if (!line_3) {
                fprintf(stderr, "Error getting GPIO %d line\n", GPIO_3);
                gpiod_chip_close(chip);
                return -1;
            }
            ret = gpiod_line_request(line_3, &config, 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d line: %d\n", GPIO_3, ret);
                gpiod_chip_close(chip);
                return -1;
            }
            break;
        case GPIO_5:
            line_5 = gpiod_chip_get_line(chip, GPIO_5);
            if (!line_5) {
                fprintf(stderr, "Error getting GPIO %d line\n", GPIO_5);
                gpiod_chip_close(chip);
                return -1;
            }
            ret = gpiod_line_request(line_5, &config, 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d line: %d\n", GPIO_5, ret);
                gpiod_chip_close(chip);
                return -1;
            }
            break;
        default:
            fprintf(stderr, "Invalid GPIO number: %d\n", gpio_num);
            return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void) {
    int ret;

    if (line_2) {
        ret = gpiod_line_release(line_2);
        if (ret < 0) {
            fprintf(stderr, "Error releasing GPIO %d line: %d\n", GPIO_2, ret);
        }
    }
    if (line_3) {
        ret = gpiod_line_release(line_3);
        if (ret < 0) {
            fprintf(stderr, "Error releasing GPIO %d line: %d\n", GPIO_3, ret);
        }
    }
    if (line_5) {
        ret = gpiod_line_release(line_5);
        if (ret < 0) {
            fprintf(stderr, "Error releasing GPIO %d line: %d\n", GPIO_5, ret);
        }
    }

    if (chip) {
        ret = gpiod_chip_close(chip);
        if (ret < 0) {
            fprintf(stderr, "Error closing GPIO chip: %d\n", ret);
        }
    }
}

int main() {
    int ret;
    unsigned int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (setup_gpio(GPIO_2) != 0 ||
        setup_gpio(GPIO_3) != 0 ||
        setup_gpio(GPIO_5) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Read current values
        ret = gpiod_line_get_value(line_2);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO %d value: %d\n", GPIO_2, ret);
            cleanup_gpio();
            return 1;
        }
        value = ret;
        ret = gpiod_line_get_value(line_3);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO %d value: %d\n", GPIO_3, ret);
            cleanup_gpio();
            return 1;
        }
        value |= (ret << 1);
        ret = gpiod_line_get_value(line_5);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO %d value: %d\n", GPIO_5, ret);
            cleanup_gpio();
            return 1;
        }
        value |= (ret << 2);

        // Print current values
        printf("GPIO 2=%d, GPIO 3=%d, GPIO 5=%d\n", (value >> 2) & 1, (value >> 1) & 1, value & 1);

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

