#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 23

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1); // Set trigger HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger LOW
}

// Function to measure the echo pulse width
long getPulseWidth()
{
    long startTime = 0, endTime = 0;
    int timeout = 100000; // Timeout after 100ms (adjust as needed)

    // Wait for echo pin to go HIGH (start of pulse)
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0)
    {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout <= 0)
    {
        fprintf(stderr, "Timeout waiting for start of pulse.\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for echo pin to go LOW (end of pulse)
    timeout = 100000;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0)
    {
        timeout--;
        gpioDelay(1);
    }

    if (timeout <= 0)
    {
        fprintf(stderr, "Timeout waiting for end of pulse.\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    return endTime - startTime;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        triggerSensor(); // Trigger the sensor
        long pulseWidth = getPulseWidth(); // Measure the pulse width

        if (pulseWidth > 0)
        {
            // Calculate distance in centimeters (speed of sound: 343 m/s)
            float distance = (pulseWidth / 1000000.0) * 34300 / 2; // Divide by 2 because of one-way travel
            printf("Distance: %.2f cm\n", distance);
        }
        else
        {
            fprintf(stderr, "Error measuring pulse width.\n");
        }

        gpioDelay(200); // Delay for 0.2 seconds (200 ms)
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for SPI communication with MCP3008
#define CS_PIN   8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 50000 // 50kHz

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel)
{
    int count = 0;
    unsigned char spi_data[3];

    // Build SPI command to read from specified channel
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008

    // Transfer SPI data
    for (int i = 0; i < 3; i++)
    {
        for (int j = 7; j >= 0; j--)
        {
            gpioWrite(MOSI_PIN, (spi_data[i] >> j) & 0x01);
            gpioWrite(SCLK_PIN, 1);
            gpioDelay(1); // Small delay for clock stability
            if (gpioRead(MISO_PIN))
            {
                count |= (1 << j);
            }
            gpioWrite(SCLK_PIN, 0);
            gpioDelay(1);
        }
    }

    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    // Extract 10-bit ADC value from received data
    return (count & 0x3FF);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for SPI pins
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);

    // Initialize SPI interface
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 50kHz, Mode 0
    if (spi_handle < 0)
    {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Read red value from MCP3008 channel 0
        int red_value = read_mcp3008(0);

        // Read green value from MCP3008 channel 1
        int green_value = read_mcp3008(1);

        // Read blue value from MCP3008 channel 2
        int blue_value = read_mcp3008(2);

        // Print the color values
        printf("R: %d, G: %d, B: %d\n", red_value, green_value, blue_value);

        // Delay for 0.01 seconds
        gpioDelay(10000); // 10000 microseconds = 0.01 seconds
    }

    // Close SPI interface
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

