#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins (BCM numbering)
#define GPIO_1 17
#define GPIO_4 27
#define GPIO_5 22
#define GPIO_6 23
#define GPIO_21 4
#define GPIO_22 5
#define GPIO_23 6
#define GPIO_24 12

// Structure to hold GPIO chip and line information
struct gpio_config {
    struct gpiod_chip *chip;
    struct gpiod_line *line[8];
};

// Global variable to store the GPIO configuration
struct gpio_config config;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int setup_gpio(struct gpio_config *config);

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpio_config *config);

// Function to set GPIO value
int set_gpio_value(struct gpio_config *config, int pin, int value);

// Function to get GPIO value
int get_gpio_value(struct gpio_config *config, int pin);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO configuration
    config.chip = NULL;
    for (int i = 0; i < 8; i++) {
        config.line[i] = NULL;
    }

    // Setup GPIO pins
    if (setup_gpio(&config) != 0) {
        fprintf(stderr, "Failed to setup GPIO pins.\n");
        return 1;
    }

    // Main loop: toggle GPIO values
    while (1) {
        for (int i = 0; i < 8; i++) {
            int current_value = get_gpio_value(&config, i);
            if (set_gpio_value(&config, i, !current_value) != 0) {
                fprintf(stderr, "Failed to set GPIO %d value.\n", i);
                cleanup_gpio(&config);
                return 1;
            }
        }
        usleep(100000); // 100ms delay
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio(&config);
    exit(0);
}

// Function to initialize GPIO lines
int setup_gpio(struct gpio_config *config) {
    // Open GPIO chip
    config->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!config->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line handles for each pin
    config->line[0] = gpiod_chip_get_line(config->chip, GPIO_1);
    config->line[1] = gpiod_chip_get_line(config->chip, GPIO_4);
    config->line[2] = gpiod_chip_get_line(config->chip, GPIO_5);
    config->line[3] = gpiod_chip_get_line(config->chip, GPIO_6);
    config->line[4] = gpiod_chip_get_line(config->chip, GPIO_21);
    config->line[5] = gpiod_chip_get_line(config->chip, GPIO_22);
    config->line[6] = gpiod_chip_get_line(config->chip, GPIO_23);
    config->line[7] = gpiod_chip_get_line(config->chip, GPIO_24);

    if (!config->line[0] || !config->line[1] || !config->line[2] || !config->line[3] ||
        !config->line[4] || !config->line[5] || !config->line[6] || !config->line[7]) {
        perror("Error getting GPIO line");
        cleanup_gpio(config);
        return -1;
    }

    // Request line as output with initial value LOW
    for (int i = 0; i < 8; i++) {
        struct gpiod_line_request_config req_config;
        memset(&req_config, 0, sizeof(req_config));
        req_config.consumer = "example";
        req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        req_config.flags = 0; // No flags needed for output

        if (gpiod_line_request(config->line[i], &req_config, 0) < 0) {
            perror("Error requesting GPIO line as output");
            cleanup_gpio(config);
            return -1;
        }
        if (gpiod_line_set_value(config->line[i], 0) < 0) {
            perror("Error setting initial value for GPIO line");
            cleanup_gpio(config);
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpio_config *config) {
    // Release line requests
    for (int i = 0; i < 8; i++) {
        if (config->line[i]) {
            gpiod_line_release(config->line[i]);
        }
    }

    // Close GPIO chip
    if (config->chip) {
        gpiod_chip_close(config->chip);
    }
}

// Function to set GPIO value
int set_gpio_value(struct gpio_config *config, int pin, int value) {
    if (pin < 0 || pin > 7) {
        fprintf(stderr, "Invalid GPIO pin number: %d\n", pin);
        return -1;
    }
    if (gpiod_line_set_value(config->line[pin], value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to get GPIO value
int get_gpio_value(struct gpio_config *config, int pin) {
    if (pin < 0 || pin > 7) {
        fprintf(stderr, "Invalid GPIO pin number: %d\n", pin);
        return -1;
    }
    int value = gpiod_line_get_value(config->line[pin]);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "captured_image.rgb"

static volatile int keep_running = 1;

void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int main()
{
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned char *buffer;
    FILE *fp;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Or V4L2_PIX_FMT_GREY
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    buffer = malloc(buf.length);
    if (!buffer) {
        perror("Error allocating memory for buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_BIND_BUFFER, &buf) < 0) {
        perror("Error binding buffer");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture loop
    while (keep_running) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 0;
        tv.tv_usec = 50000; // 0.05 seconds

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            perror("Error in select");
            break;
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            continue;
        }

        // Dequeue buffer
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        // Copy data to file
        fp = fopen(IMAGE_FILE, "wb");
        if (!fp) {
            perror("Error opening image file");
            free(buffer);
            close(fd);
            break;
        }

        fwrite(buffer, buf.bytesused, 1, fp);
        fclose(fp);

        printf("Captured image saved to %s\n", IMAGE_FILE);

        // Requeue buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error requeuing buffer");
            break;
        }
    }

    // Stop streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    // Unbind buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_UNBIND_BUFFER, &buf) < 0) {
        perror("Error unbinding buffer");
    }

    // Free buffer
    free(buffer);

    // Close device
    close(fd);

    return EXIT_SUCCESS;
}

