        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (bme280_write_register(handle, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (bme280_write_register(handle, BME280_REG_CONFIG, 0x00) < 0) {
        return -1;
    }

