        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to configure the ADS1115
int ads1115_config(int fd) {
    // Configure for single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint16_t config = 0x4083; // 0b0100000010000011
    uint8_t msb = (config >> 8) & 0xFF;
    uint8_t lsb = config & 0xFF;

    if (i2c_write_reg(fd, ADS1115_REG_CONFIG, msb) != 0) return -1;
    if (i2c_write_reg(fd, ADS1115_REG_CONFIG + 1, lsb) != 0) return -1;

    return 0;
}

// Function to read the conversion result
int16_t ads1115_read_conversion(int fd) {
    uint8_t msb, lsb;

    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION, &msb) != 0) return -1;
    if (i2c_read_reg(fd, ADS1115_REG_CONVERSION + 1, &lsb) != 0) return -1;

    return (int16_t)((msb << 8) | lsb);
}

