int mpu6050_init(int fd) {
    // Wake up the MPU6050 (set sleep bit to 0)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Clear sleep mode bit

    if (write(fd, data, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1");
        return -1;
    }
    usleep(10000); // Short delay after initialization
    return 0;
}

