int read_accel_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    uint8_t reg = ACCEL_XOUT_H;
    uint8_t buffer[6];

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to register");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *accel_x = (buffer[0] << 8) | buffer[1];
    *accel_y = (buffer[2] << 8) | buffer[3];
    *accel_z = (buffer[4] << 8) | buffer[5];

    return 0;
}

