// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth()
{
    long startTime = 0, endTime = 0;
    int startSec, startUSec, endSec, endUSec;

    // Wait for echo pin to go high (with timeout)
    long timeoutStart = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - timeoutStart > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    gpioTime(0, &startSec, &startUSec);
    startTime = startSec * 1000000 + startUSec;

    // Wait for echo pin to go low (with timeout)
    timeoutStart = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - timeoutStart > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    gpioTime(0, &endSec, &endUSec);
    endTime = endSec * 1000000 + endUSec;

    return endTime - startTime;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulseWidth)
{
    if (pulseWidth < 0) {
        return -1.0; // Indicate error
    }

    float timeInSeconds = (float)pulseWidth / 1000000.0;
    float distance = (SPEED_OF_SOUND * timeInSeconds) / 2.0;

    return distance;
}

