// Format MQTT payload with timestamp
char* format_mqtt_payload(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    static char payload[50]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"sensor_value\": %d}", timestamp, sensor_value);

    return payload;
}

// Publish MQTT message
int publish_mqtt_message(struct mosquitto *mosq, const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

