    terminate = 1;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 192); // 75% duty cycle
        gpioPWM(PWM_PIN_3, 64);  // 25% duty cycle
        gpioPWM(PWM_PIN_4, 255); // 100% duty cycle

        // Print current PWM settings
        printf("PWM_PIN_1: 50%%, PWM_PIN_2: 75%%, PWM_PIN_3: 25%%, PWM_PIN_4: 100%%\n");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Release GPIO pins and terminate pigpio library
    gpioTerminate();

    return 0;
}

