// Configuration parameters (default values)
#define DEFAULT_DEVICE_ID "RPi1"
#define DEFAULT_MQTT_BROKER "localhost"
#define DEFAULT_MQTT_PORT 1883
#define DEFAULT_MQTT_TOPIC "sensor_data"
#define DEFAULT_SENSOR_READ_INTERVAL_MS 500

// Global variables (try to minimize)
static char *device_id = DEFAULT_DEVICE_ID;
static char *mqtt_broker = DEFAULT_MQTT_BROKER;
static int mqtt_port = DEFAULT_MQTT_PORT;
static char *mqtt_topic = DEFAULT_MQTT_TOPIC;
static int sensor_read_interval_ms = DEFAULT_SENSOR_READ_INTERVAL_MS;
static int sockfd = -1; // Socket file descriptor
static volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    char *device_id;
    char *mqtt_broker;
    int mqtt_port;
    char *mqtt_topic;
    int sensor_read_interval_ms;
} config_t;

// Function prototypes
void signal_handler(int sig);
int parse_arguments(int argc, char *argv[], config_t *config);
int connect_mqtt(const char *broker, int port);
int publish_message(int sockfd, const char *topic, const char *payload);
void cleanup(int sockfd);
char* get_sensor_reading();
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[], config_t *config) {
    int opt;

    while ((opt = getopt(argc, argv, "d:b:p:t:i:")) != -1) {
        switch (opt) {
            case 'd':
                config->device_id = optarg;
                break;
            case 'b':
                config->mqtt_broker = optarg;
                break;
            case 'p':
                config->mqtt_port = atoi(optarg);
                break;
            case 't':
                config->mqtt_topic = optarg;
                break;
            case 'i':
                config->sensor_read_interval_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device_id] [-b broker_address] [-p port] [-t topic] [-i interval_ms]\n", argv[0]);
                return 1;
        }
    }

    return 0;
}

// Connect to MQTT broker
int connect_mqtt(const char *broker, int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, broker, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connect");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Publish message to MQTT broker
int publish_message(int sockfd, const char *topic, const char *payload) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "{\"device_id\": \"%s\", \"timestamp\": \"%ld\", \"data\": \"%s\"}", device_id, time(NULL), payload);

    // Construct MQTT packet (very basic example, needs proper framing for real use)
    char mqtt_packet[256];
    snprintf(mqtt_packet, sizeof(mqtt_packet), "$$MQTT$$%s$$%s$$%s$$", device_id, topic, buffer);

    ssize_t bytes_sent = send(sockfd, mqtt_packet, strlen(mqtt_packet), 0);
    if (bytes_sent < 0) {
        perror("send");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(int sockfd) {
    if (sockfd != -1) {
        close(sockfd);
    }
    printf("Cleanup complete.\n");
}

// Get sensor reading (replace with actual sensor reading logic)
char* get_sensor_reading() {
    // Simulate sensor reading (replace with actual sensor reading)
    static char reading[32]; // Static to persist across calls
    snprintf(reading, sizeof(reading), "Temperature: 25.5C, Humidity: 60%");
    return reading;
}

// Log error messages
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main(int argc, char *argv[]) {
    config_t config = { .device_id = DEFAULT_DEVICE_ID,
                        .mqtt_broker = DEFAULT_MQTT_BROKER,
                        .mqtt_port = DEFAULT_MQTT_PORT,
                        .mqtt_topic = DEFAULT_MQTT_TOPIC,
                        .sensor_read_interval_ms = DEFAULT_SENSOR_READ_INTERVAL_MS };

    if (parse_arguments(argc, argv, &config) != 0) {
        return 1;
    }

    device_id = config.device_id;
    mqtt_broker = config.mqtt_broker;
    mqtt_port = config.mqtt_port;
    mqtt_topic = config.mqtt_topic;
    sensor_read_interval_ms = config.sensor_read_interval_ms;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    sockfd = connect_mqtt(mqtt_broker, mqtt_port);
    if (sockfd < 0) {
        log_error("Failed to connect to MQTT broker.");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get sensor reading
        char *sensor_reading = get_sensor_reading();

        // Publish message
        if (publish_message(sockfd, mqtt_topic, sensor_reading) == 0) {
            printf("Published: %s\n", sensor_reading);
        } else {
            log_error("Failed to publish message.");
        }

        // Wait before next reading
        usleep(sensor_read_interval_ms * 1000); // Convert ms to microseconds
    }

    // Cleanup resources
    cleanup(sockfd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define CONFIG_FILE "config.txt"
#define DEFAULT_I2C_ADDR 0x48
#define DEFAULT_MQTT_HOST "localhost"
#define DEFAULT_MQTT_PORT 1883
#define DEFAULT_MQTT_TOPIC "sensor/ads1115"

// ADS1115 Registers
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
int running = 1;

// Function prototypes
int read_config(int *i2c_address, char **mqtt_host, int *mqtt_port, char **mqtt_topic);
int ads1115_read(int i2c_handle, int16_t *value);
int publish_sensor_data(struct mosquitto *mosq, const char *topic, int16_t value);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting gracefully.\n", signum);
        running = 0;
    }
}

// Function to read configuration from file
int read_config(int *i2c_address, char **mqtt_host, int *mqtt_port, char **mqtt_topic) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "i2c_address") == 0) {
                *i2c_address = strtol(value, NULL, 0);
            } else if (strcmp(key, "mqtt_host") == 0) {
                *mqtt_host = strdup(value);
            } else if (strcmp(key, "mqtt_port") == 0) {
                *mqtt_port = atoi(value);
            } else if (strcmp(key, "mqtt_topic") == 0) {
                *mqtt_topic = strdup(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to read data from ADS1115
int ads1115_read(int i2c_handle, int16_t *value) {
    uint8_t config[3];
    uint8_t convert[2];

    // Configure ADS1115 for single conversion, AIN0, +/-4.096V, 128 SPS
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC3 | (0b000 << 12); // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // MSB

    if (i2cWriteDevice(i2c_handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion result
    convert[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, (char *)convert, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 convert register\n");
        return -1;
    }

    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 convert register\n");
        return -1;
    }

    *value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

// Function to publish sensor data to MQTT broker
int publish_sensor_data(struct mosquitto *mosq, const char *topic, int16_t value) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", value);

    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    int i2c_address = DEFAULT_I2C_ADDR;
    char *mqtt_host = strdup(DEFAULT_MQTT_HOST);
    int mqtt_port = DEFAULT_MQTT_PORT;
    char *mqtt_topic = strdup(DEFAULT_MQTT_TOPIC);

    // Read configuration from file
    if (read_config(&i2c_address, &mqtt_host, &mqtt_port, &mqtt_topic) != 0) {
        fprintf(stderr, "Using default configuration.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, mqtt_host, mqtt_port, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        i2cClose(i2c_handle);
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t sensor_value;
    // Main loop
    for (int i = 0; i < 10 && running; ++i) {
        if (ads1115_read(i2c_handle, &sensor_value) == 0) {
            if (publish_sensor_data(mosq, mqtt_topic, sensor_value) != 0) {
                fprintf(stderr, "Failed to publish sensor data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    i2cClose(i2c_handle);
    gpioTerminate();

    free(mqtt_host);
    free(mqtt_topic);

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
