#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_17 = NULL;
static struct gpiod_line *line_18 = NULL;

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");

    if (line_17) {
        gpiod_line_set_value(line_17, 0);
        gpiod_line_release(line_17);
    }
    if (line_18) {
        gpiod_line_set_value(line_18, 0);
        gpiod_line_release(line_18);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(signum);
}

int main() {
    int ret;
    unsigned int value_17, value_18;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'.\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Get line for GPIO 17
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        fprintf(stderr, "Error: Could not get line for GPIO %d.\n", GPIO_17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get line for GPIO 18
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        fprintf(stderr, "Error: Could not get line for GPIO %d.\n", GPIO_18);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output
    ret = gpiod_line_request_output(line_17, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %d\n", GPIO_17, ret);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_18, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %d\n", GPIO_18, ret);
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 17
        value_17 = !value_17;
        ret = gpiod_line_set_value(line_17, value_17);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %d\n", GPIO_17, ret);
            break; // Exit loop on error
        }

        // Toggle GPIO 18
        value_18 = !value_18;
        ret = gpiod_line_set_value(line_18, value_18);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %d\n", GPIO_18, ret);
            break; // Exit loop on error
        }

        // Print current state
        printf("GPIO 17: %d, GPIO 18: %d\n", value_17, value_18);

        usleep(50000); // 0.05 seconds
    }

    // Cleanup (should not reach here if error occurred in loop)
    cleanup(EXIT_FAILURE);

    return EXIT_SUCCESS;
}

