#define GPIO_23 23

static struct gpiod_chip *chip;
static struct gpiod_line *line_17, *line_23;

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_23) {
        gpiod_line_release(line_23);
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get the GPIO line for GPIO 17
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line_17) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the GPIO line for GPIO 23
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line_23) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_23);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(line_17, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_17);
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_23, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output\n", GPIO_23);
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 17 high
    if (set_gpio_value(line_17, 1) != 0) {
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO 23 low
    if (set_gpio_value(line_23, 0) != 0) {
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 17 set HIGH, GPIO 23 set LOW\n");

    // Release GPIO lines and close chip before exiting
    gpiod_line_release(line_17);
    gpiod_line_release(line_23);
    gpiod_chip_close(chip);

    return 0;
