#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>

#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    int fd;
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;

    // Set up signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    // Open the serial port
    fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Configure the serial port
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        exit(EXIT_FAILURE);
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;   // Read doesn't block
    tty.c_cc[VTIME] = 5;  // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        exit(EXIT_FAILURE);
    }

    printf("Reading from %s at %d baud...\n", UART_PORT, B115200);

    while (keep_running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("%s", buffer);
        } else if (bytes_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("read");
            break;
        } else {
            usleep(10000); // Small delay to avoid busy-waiting
        }
    }

    // Restore terminal settings
    tcsetattr(fd, TCSANOW, NULL);

    // Close the serial port
    close(fd);

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an MPU6050 register
int read_register(int handle, uint8_t reg) {
    return i2cReadByteData(handle, reg);
}

// Function to write a single byte to an MPU6050 register
int write_register(int handle, uint8_t reg, uint8_t value) {
    return i2cWriteByteData(handle, reg, value);
}

// Function to initialize the MPU6050
int init_mpu6050(int handle) {
    // Wake up the MPU6050 (set sleep bit to 0)
    if (write_register(handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, 0x68, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (address 0x68)\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (!terminate) {
        int16_t x, y, z;

        if (read_accelerometer_data(i2c_handle, &x, &y, &z) == 0) {
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data in main loop\n");
        }

        gpioDelay(100); // Delay for 0.1 seconds (100 ms)
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read calibration data from BMP280
int read_calibration_data() {
    char buf[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, buf, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    calib.dig_T2 = (int16_t)buf[2] | ((int16_t)buf[3] << 8);
    calib.dig_T3 = (int16_t)buf[4] | ((int16_t)buf[5] << 8);
    calib.dig_P1 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    calib.dig_P2 = (int16_t)buf[8] | ((int16_t)buf[9] << 8);
    calib.dig_P3 = (int16_t)buf[10] | ((int16_t)buf[11] << 8);
    calib.dig_P4 = (int16_t)buf[12] | ((int16_t)buf[13] << 8);
    calib.dig_P5 = (int16_t)buf[14] | ((int16_t)buf[15] << 8);
    calib.dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    calib.dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    calib.dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
    calib.dig_P9 = (int16_t)buf[22] | ((int16_t)buf[23] << 8);

    return 0;
}

// Function to initialize the BMP280 sensor
int init_bmp280() {
    // Check the device ID
    char id;
    if (i2cReadByteData(i2c_handle, BMP280_REG_ID) != 0x58) {
        fprintf(stderr, "Error: Invalid device ID\n");
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        return -1;
    }

    // Set oversampling and power mode
    // Temperature oversampling x1, pressure oversampling x1, normal mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register\n");
        return -1;
    }

    // Set filter coefficient and standby time
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature and pressure values
int read_raw_data(int32_t *raw_temperature, int32_t *raw_pressure) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *raw_pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *raw_temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) *
            (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) *
           ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure) {
    double var1, var2, p;
    double t_fine = 0.0; // Dummy value, needs to be calculated in compensate_temperature

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure);

            // Print the compensated values
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    int duty_cycle;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Prompt user for duty cycle
    printf("Enter duty cycle (0-255): ");
    result = scanf("%d", &duty_cycle);

    if (result != 1) {
        fprintf(stderr, "Invalid input. Please enter a number between 0 and 255.\n");
        gpioTerminate();
        return 1;
    }

    // Validate duty cycle
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Duty cycle out of range (0-255). Using default value of 128.\n");
        duty_cycle = 128;
    }

    // Set PWM duty cycle
    gpioPWM(PWM_PIN, duty_cycle);

    // Print current state
    printf("PWM pin %d set to duty cycle %d\n", PWM_PIN, duty_cycle);

    // Keep the program running until a signal is received
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and terminate pigpio
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

static struct gpiod_chip *chip;
static struct gpiod_line *line5, *line6, *line13;

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);

    // Close the chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get the GPIO lines
    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);

    if (!line5 || !line6 || !line13) {
        fprintf(stderr, "Error getting GPIO line\n");
        goto cleanup;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(line5, "myapp", 0) < 0 ||
        gpiod_line_request_output(line6, "myapp", 0) < 0 ||
        gpiod_line_request_output(line13, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        goto cleanup;
    }

    // Set initial values
    if (set_gpio_value(line5, 1) != 0 ||
        set_gpio_value(line6, 0) != 0 ||
        set_gpio_value(line13, 1) != 0) {
        goto cleanup;
    }

    // Print current values
    printf("GPIO 5: %s\n", gpiod_line_is_active_low(line5) ? "LOW" : "HIGH");
    printf("GPIO 6: %s\n", gpiod_line_is_active_low(line6) ? "LOW" : "HIGH");
    printf("GPIO 13: %s\n", gpiod_line_is_active_low(line13) ? "LOW" : "HIGH");

cleanup:
    // Release GPIO lines
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);

    // Close the chip
    if (chip) gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration structure
typedef struct {
    char mqtt_broker_address[256];
    int mqtt_broker_port;
    char mqtt_client_id[128];
    char mqtt_username[64];
    char mqtt_password[64];
    char mqtt_topic[256];
    int gpio_pin;
} config_t;

// Global variables
config_t config;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int load_config(const char *filename, config_t *config);
void signal_handler(int signum);
int connect_mqtt(struct mosquitto **mosq, const char *client_id, const char *broker_address, int broker_port, const char *username, const char *password);
int publish_message(struct mosquitto *mosq, const char *topic, const char *payload);
void cleanup(void);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d, terminating...\n", signum);
        terminate = 1;
    }
}

// Load configuration from file
int load_config(const char *filename, config_t *config) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key && value) {
            if (strcmp(key, "mqtt_broker_address") == 0) {
                strncpy(config->mqtt_broker_address, value, sizeof(config->mqtt_broker_address) - 1);
                config->mqtt_broker_address[sizeof(config->mqtt_broker_address) - 1] = '\0';
            } else if (strcmp(key, "mqtt_broker_port") == 0) {
                config->mqtt_broker_port = atoi(value);
            } else if (strcmp(key, "mqtt_client_id") == 0) {
                strncpy(config->mqtt_client_id, value, sizeof(config->mqtt_client_id) - 1);
                config->mqtt_client_id[sizeof(config->mqtt_client_id) - 1] = '\0';
            } else if (strcmp(key, "mqtt_username") == 0) {
                strncpy(config->mqtt_username, value, sizeof(config->mqtt_username) - 1);
                config->mqtt_username[sizeof(config->mqtt_username) - 1] = '\0';
            } else if (strcmp(key, "mqtt_password") == 0) {
                strncpy(config->mqtt_password, value, sizeof(config->mqtt_password) - 1);
                config->mqtt_password[sizeof(config->mqtt_password) - 1] = '\0';
            } else if (strcmp(key, "mqtt_topic") == 0) {
                strncpy(config->mqtt_topic, value, sizeof(config->mqtt_topic) - 1);
                config->mqtt_topic[sizeof(config->mqtt_topic) - 1] = '\0';
            } else if (strcmp(key, "gpio_pin") == 0) {
                config->gpio_pin = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Connect to MQTT broker
int connect_mqtt(struct mosquitto **mosq, const char *client_id, const char *broker_address, int broker_port, const char *username, const char *password) {
    int rc;

    mosquitto_lib_init();
    *mosq = mosquitto_new(client_id, true, NULL);
    if (!*mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    if (username && password) {
        mosquitto_username_pw_set(*mosq, username, password);
    }

    rc = mosquitto_connect(*mosq, broker_address, broker_port, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(*mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    return 0;
}

// Publish message to MQTT broker
int publish_message(struct mosquitto *mosq, const char *topic, const char *payload) {
    int rc = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(rc));
        return 1;
    }
    return 0;
}

// Cleanup resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up...\n");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }

    mosquitto_lib_cleanup();

    gpioTerminate();

    exit(0);
}

int main() {
    // Load configuration
    if (load_config("config.txt", &config) != 0) {
        fprintf(stderr, "Failed to load configuration. Exiting.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(config.gpio_pin, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    if (connect_mqtt(&mosq, config.mqtt_client_id, config.mqtt_broker_address, config.mqtt_broker_port, config.mqtt_username, config.mqtt_password) != 0) {
        fprintf(stderr, "Failed to connect to MQTT broker. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor value
        int sensor_value = gpioRead(config.gpio_pin);

        // Format sensor data with timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        char payload[256];
        snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"sensor_value\": %d}", timestamp, sensor_value);

        // Publish message
        if (publish_message(mosq, config.mqtt_topic, payload) != 0) {
            fprintf(stderr, "Failed to publish message. Retrying in 5 seconds.\n");
            sleep(5);
            continue; // Retry publishing
        }

        printf("Published: %s\n", payload);

        // Wait before next reading
