// Define UART port (check your Raspberry Pi configuration)
#define UART_PORT "/dev/ttyAMA0"

// Define baud rate
#define BAUD_RATE B115200

// Global variable for file descriptor
int uart_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    if (uart_fd != -1) {
        close(uart_fd);
    }
    exit(0);
}

// Function to initialize UART
int init_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    // Configure UART settings
    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    // Set timeout to non-blocking
    tty.c_cc[VMIN] = 0;   // Read at least 0 characters
    tty.c_cc[VTIME] = 0;  // Wait for 0 tenths of a second

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    printf("UART initialized successfully. Reading from %s at %d baud.\n", UART_PORT, B115200);

    // Main loop: read data from UART and print to stdout
    unsigned char buffer[256]; // Buffer to store received data
    ssize_t bytes_read;

    while ((bytes_read = read(uart_fd, buffer, sizeof(buffer))) > 0) {
        // Process the received data (e.g., convert to integer)
        int value = *((int *)buffer); // Assuming data is a 32-bit integer

        // Validate the received value
        if (value >= 0 && value <= 100) {
            printf("Received value: %d\n", value);
        } else {
            fprintf(stderr, "Warning: Received value out of range (%d). Discarding.\n", value);
        }
    }

    // Close UART port
    close(uart_fd);
    uart_fd = -1; // Reset the global variable

    printf("Data exchange complete. Exiting.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

static struct gpiod_chip *chip;
static struct gpiod_line *line_18, *line_23, *line_24;

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_18) gpiod_line_release(line_18);
    if (line_23) gpiod_line_release(line_23);
    if (line_24) gpiod_line_release(line_24);

    // Close the chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get the GPIO lines
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line_18 || !line_23 || !line_24) {
        fprintf(stderr, "Error getting GPIO line(s)\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    int ret = gpiod_line_request_output(line_18, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_18, ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_23, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_23, ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_24, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_24, ret);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial values
    if (set_gpio_value(line_18, 1) != 0) return 1;
    if (set_gpio_value(line_23, 0) != 0) return 1;
    if (set_gpio_value(line_24, 1) != 0) return 1;

    // Print current values
    printf("GPIO %d: %d\n", GPIO_18, gpiod_line_get_value(line_18));
    printf("GPIO %d: %d\n", GPIO_23, gpiod_line_get_value(line_23));
    printf("GPIO %d: %d\n", GPIO_24, gpiod_line_get_value(line_24));

    // Clean up and exit
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_PIN, 1000);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop: adjust PWM duty cycle
    while (!terminate) {
        // Example: Increase duty cycle gradually
        int duty_cycle = 0;
        while (duty_cycle <= 255 && !terminate) {
            gpioPWM(PWM_PIN, duty_cycle);
            printf("PWM duty cycle: %d\n", duty_cycle);
            fflush(stdout); // Ensure immediate output
            gpioDelay(10000); // Delay for 10ms (adjust as needed)
            duty_cycle += 5; // Increment duty cycle by 5%
        }

        // Example: Decrease duty cycle gradually
        while (duty_cycle >= 0 && !terminate) {
            gpioPWM(PWM_PIN, duty_cycle);
            printf("PWM duty cycle: %d\n", duty_cycle);
            fflush(stdout); // Ensure immediate output
            gpioDelay(10000); // Delay for 10ms (adjust as needed)
            duty_cycle -= 5; // Decrement duty cycle by 5%
        }
    }

    // Release GPIO and terminate pigpio
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    if (line != NULL) {
        // Release the line
        int ret = gpiod_line_release(line);
        if (ret < 0) {
            fprintf(stderr, "Error releasing line: %s\n", strerror(-ret));
        }
        line = NULL;
    }

    if (chip != NULL) {
        // Close the chip
        int ret = gpiod_chip_close(chip);
        if (ret < 0) {
            fprintf(stderr, "Error closing chip: %s\n", strerror(-ret));
        }
        chip = NULL;
    }

    exit(0);
}

int main()
{
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "example";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle the GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(-value));
            break; // Exit loop on error
        }
        int new_value = !value;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Error writing to GPIO line %d: %s\n", GPIO_PIN, strerror(-ret));
            break; // Exit loop on error
        }

        // Print the current state
        printf("GPIO %d set to %d\n", GPIO_PIN, new_value);

        // Wait for 2 seconds
        sleep(2);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return 0;
}

