#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int read_dht22(float *temperature, float *humidity) {
    int i, j;
    int data[5] = {0, 0, 0, 0, 0};
    unsigned int tick;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - tick > 200) return -1; // Timeout
    }

    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 0) {
        if (gpioTick() - tick > 200) return -1; // Timeout
    }

    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - tick > 200) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - tick > 200) return -1; // Timeout
        }

        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - tick > 200) return -1; // Timeout
        }

        if ((gpioTick() - tick) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1; // Checksum failure
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    result = read_dht22(&temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "DHT22 read failed\n");
    }

    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

// Define chip name (adjust as needed)
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_17, *line_23, *line_24, *line_25;

// Function prototypes
int setup_gpio(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO function
int setup_gpio(int pin) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", CHIP_NAME);
        return -1;
    }

    // Get line handle
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line for output
    ret = gpiod_line_request_output(line, "myapp", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", pin);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void) {
    if (line_17) {
        gpiod_line_set_value(line_17, 0); // Set to LOW before releasing
        gpiod_line_release(line_17);
    }
    if (line_23) {
        gpiod_line_set_value(line_23, 0); // Set to LOW before releasing
        gpiod_line_release(line_23);
    }
    if (line_24) {
        gpiod_line_set_value(line_24, 0); // Set to LOW before releasing
        gpiod_line_release(line_24);
    }
    if (line_25) {
        gpiod_line_set_value(line_25, 0); // Set to LOW before releasing
        gpiod_line_release(line_25);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (setup_gpio(GPIO_17) != 0 ||
        setup_gpio(GPIO_23) != 0 ||
        setup_gpio(GPIO_24) != 0 ||
        setup_gpio(GPIO_25) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO pins\n");
        cleanup_gpio();
        return 1;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);
    line_25 = gpiod_chip_get_line(chip, GPIO_25);

    // Main loop
    while (1) {
        // Toggle GPIO 17
        if (gpiod_line_get_value(line_17) == 0) {
            gpiod_line_set_value(line_17, 1);
        } else {
            gpiod_line_set_value(line_17, 0);
        }

        // Toggle GPIO 23
        if (gpiod_line_get_value(line_23) == 0) {
            gpiod_line_set_value(line_23, 1);
        } else {
            gpiod_line_set_value(line_23, 0);
        }

        // Toggle GPIO 24
        if (gpiod_line_get_value(line_24) == 0) {
            gpiod_line_set_value(line_24, 1);
        } else {
            gpiod_line_set_value(line_24, 0);
        }

        // Toggle GPIO 25
        if (gpiod_line_get_value(line_25) == 0) {
            gpiod_line_set_value(line_25, 1);
        } else {
            gpiod_line_set_value(line_25, 0);
        }

        // Print current state
        printf("GPIO 17: %d, GPIO 23: %d, GPIO 24: %d, GPIO 25: %d\n",
               gpiod_line_get_value(line_17),
               gpiod_line_get_value(line_23),
               gpiod_line_get_value(line_24),
               gpiod_line_get_value(line_25));

        sleep(10);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration structure
typedef struct {
    char mqtt_broker[100];
    char mqtt_topic[100];
    int spi_channel;
    int mcp3008_channel;
} config_t;

// Global variables
config_t config;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t running = 1;

// Function prototypes
int read_mcp3008(int channel);
void publish_sensor_data(int adc_value);
void signal_handler(int signum);
int load_config(const char *filename, config_t *config);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    buffer[2] = 0x00;

    wiringPiSPIDataRW(config.spi_channel, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to publish sensor data to MQTT broker
void publish_sensor_data(int adc_value) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", adc_value);

    int ret = mosquitto_publish(mosq, NULL, config.mqtt_topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing: %s\n", mosquitto_strerror(ret));
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signum);
}

// Function to load configuration from file
int load_config(const char *filename, config_t *config) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char key[50], value[100];
        if (sscanf(line, "%49[^=]=%99[^\n]", key, value) == 2) {
            if (strcmp(key, "mqtt_broker") == 0) {
                strncpy(config->mqtt_broker, value, sizeof(config->mqtt_broker) - 1);
                config->mqtt_broker[sizeof(config->mqtt_broker) - 1] = '\0';
            } else if (strcmp(key, "mqtt_topic") == 0) {
                strncpy(config->mqtt_topic, value, sizeof(config->mqtt_topic) - 1);
                config->mqtt_topic[sizeof(config->mqtt_topic) - 1] = '\0';
            } else if (strcmp(key, "spi_channel") == 0) {
                config->spi_channel = atoi(value);
            } else if (strcmp(key, "mcp3008_channel") == 0) {
                config->mcp3008_channel = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    // Load configuration from file
    if (load_config("config.txt", &config) != 0) {
        fprintf(stderr, "Failed to load configuration. Exiting.\n");
