#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        return 1;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    // Check if the device is a video capture device
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return 1;
    }

    // Set the image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Use MJPEG for compression
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Capture the image
    FILE *fp = fopen("captured_image.jpg", "wb");
    if (!fp) {
        perror("Error opening output file");
        close(fd);
        return 1;
    }

    unsigned char buffer[1024]; // Adjust buffer size as needed
    int bytes_read;
    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        fwrite(buffer, 1, bytes_read, fp);
    }

    fclose(fp);

    printf("Image saved as captured_image.jpg\n");

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);
    gpioSetMode(PWM_PIN_6, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 192); // 75% duty cycle
        gpioPWM(PWM_PIN_3, 255); // 100% duty cycle
        gpioPWM(PWM_PIN_4,  64); // 25% duty cycle
        gpioPWM(PWM_PIN_5,  96); // 37.5% duty cycle
        gpioPWM(PWM_PIN_6,   0); // 0% duty cycle

        // Print current PWM settings
        printf("PWM_PIN_1: 50%%, PWM_PIN_2: 75%%, PWM_PIN_3: 100%%, PWM_PIN_4: 25%%, PWM_PIN_5: 37.5%%, PWM_PIN_6: 0%%\n");

        // Delay for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Release GPIO pins and terminate pigpio library
    gpioTerminate();

    return 0;
}

