#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1); // Set trigger HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger LOW
}

// Function to measure the echo pulse width
long getPulseWidth()
{
    long startTime = 0, endTime = 0;
    int timeout = 100000; // Timeout after 100ms (adjust as needed)

    // Wait for echo pin to go HIGH (start of pulse)
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0)
    {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout <= 0)
    {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1; // Indicate timeout error
    }
    startTime = gpioTick();

    // Wait for echo pin to go LOW (end of pulse)
    timeout = 100000;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0)
    {
        timeout--;
        gpioDelay(1);
    }

    if (timeout <= 0)
    {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1; // Indicate timeout error
    }
    endTime = gpioTick();

    return endTime - startTime;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        triggerSensor();
        long pulseWidth = getPulseWidth();

        if (pulseWidth > 0)
        {
            // Calculate distance in centimeters (speed of sound: 343 m/s)
            float distance = (pulseWidth / 2.0) * 0.0343;
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Invalid pulse width\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Release GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

