#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FILE "captured_image.rgb"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    FILE *fp;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Or V4L2_PIX_FMT_GREY
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    buffer = malloc(buf.length);
    if (!buffer) {
        perror("Error allocating memory for buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset) == MAP_FAILED) {
        perror("Error mapping buffer");
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Queue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Capture image
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buffer, buf.length);
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("Error opening image file");
        munmap(buffer, buf.length);
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    fwrite(buffer, buf.bytesused, 1, fp);
    fclose(fp);

    printf("Image saved to %s\n", IMAGE_FILE);

    // Requeue the buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        munmap(buffer, buf.length);
        free(buffer);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        munmap(buffer, buf.length);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap the buffer
    munmap(buffer, buf.length);
    free(buffer);

    // Close the device
    close(fd);

    return EXIT_SUCCESS;
}

