#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

// Define MPU6050 I2C address
#define MPU6050_ADDR 0x68

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an MPU6050 register
int read_register(int handle, uint8_t reg) {
    return i2cReadByteData(handle, reg);
}

// Function to write a single byte to an MPU6050 register
int write_register(int handle, uint8_t reg, uint8_t value) {
    return i2cWriteByteData(handle, reg, value);
}

// Function to initialize the MPU6050
int init_mpu6050(int handle) {
    // Wake up the MPU6050 (set sleep bit to 0)
    if (write_register(handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_accelerometer_data(i2c_handle, &x, &y, &z) == 0) {
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data in main loop\n");
        }
        usleep(100000); // 0.1 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

static struct gpiod_chip *chip;
static struct gpiod_line *line_2, *line_3, *line_17;

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// Function to read the GPIO line value
int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value\n");
        return -1;
    }
    return value;
}

// Function to validate the GPIO value
int validate_gpio_value(int value) {
    return (value == 0 || value == 1) ? 0 : -1; // Return 0 for valid, -1 for invalid
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_2 != NULL) gpiod_line_release(line_2);
    if (line_3 != NULL) gpiod_line_release(line_3);
    if (line_17 != NULL) gpiod_line_release(line_17);

    // Close GPIO chip
    if (chip != NULL) gpiod_chip_close(chip);

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_2 || !line_3 || !line_17) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_2, "myapp", 0) < 0 ||
        gpiod_line_request_output(line_3, "myapp", 0) < 0 ||
        gpiod_line_request_output(line_17, "myapp", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; ++i) {
        // Cycle 1: GPIO 2 HIGH, GPIO 3 LOW, GPIO 17 HIGH
        if (set_gpio_value(line_2, 1) < 0 ||
            set_gpio_value(line_3, 0) < 0 ||
            set_gpio_value(line_17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO values\n");
            break;
        }
        printf("Cycle %d: GPIO 2=HIGH, GPIO 3=LOW, GPIO 17=HIGH\n", i + 1);
        sleep(5);

        // Cycle 2: GPIO 2 LOW, GPIO 3 HIGH, GPIO 17 LOW
        if (set_gpio_value(line_2, 0) < 0 ||
            set_gpio_value(line_3, 1) < 0 ||
            set_gpio_value(line_17, 0) < 0) {
            fprintf(stderr, "Error setting GPIO values\n");
            break;
        }
        printf("Cycle %d: GPIO 2=LOW, GPIO 3=HIGH, GPIO 17=LOW\n", i + 1);
        sleep(5);

        // Cycle 3: GPIO 2 HIGH, GPIO 3 HIGH, GPIO 17 HIGH
        if (set_gpio_value(line_2, 1) < 0 ||
            set_gpio_value(line_3, 1) < 0 ||
            set_gpio_value(line_17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO values\n");
            break;
        }
        printf("Cycle %d: GPIO 2=HIGH, GPIO 3=HIGH, GPIO 17=HIGH\n", i + 1);
        sleep(5);
    }

    // Release GPIO lines
    if (line_2 != NULL) gpiod_line_release(line_2);
    if (line_3 != NULL) gpiod_line_release(line_3);
    if (line_17 != NULL) gpiod_line_release(line_17);

    // Close GPIO chip
    if (chip != NULL) gpiod_chip_close(chip);

    return 0;
}

