#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SHT31_ADDR 0x44

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from SHT31
int read_sht31(float *temperature, float *humidity) {
    unsigned char cmd[2] = {0x24, 0x00}; // High repeatability, clock stretching disabled
    unsigned char buf[6];
    int ret;

    // Send measurement command
    ret = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", ret);
        return -1;
    }

    // Wait for measurement (typical 10ms, max 15ms)
    gpioDelay(20);

    // Read 6 bytes of data
    ret = i2cReadDevice(i2c_handle, (char *)buf, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", ret);
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    uint16_t hum_raw = (buf[3] << 8) | buf[4];

    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int ret;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        ret = read_sht31(&temperature, &humidity);
        if (ret == 0) {
            // Validate readings
            if (temperature > -40.0 && temperature < 125.0 && humidity > 0.0 && humidity < 100.0) {
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Invalid temperature or humidity reading\n");
            }
        } else {
            fprintf(stderr, "Failed to read SHT31 data\n");
        }

        sleep(5);
    }

    // Cleanup (should not reach here in normal execution due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 10

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[GPIO_LINES];
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main()
{
    int i, ret;
    unsigned int value;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        fprintf(stderr, "Error: GPIO chip '%s' not found.\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Get line handles
    for (i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            fprintf(stderr, "Error: Could not get line %d from chip '%s'.\n", i, GPIO_CHIP);
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Request lines as outputs
    for (i = 0; i < GPIO_LINES; i++) {
        ret = gpiod_line_request_output(lines[i], "example", 0);
        if (ret < 0) {
            perror("Error requesting GPIO line as output");
            fprintf(stderr, "Error: Could not request line %d as output.\n", i);
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set initial values
    for (i = 0; i < GPIO_LINES; i++) {
        value = (i % 2 == 0) ? 1 : 0;
        ret = gpiod_line_set_value(lines[i], value);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            fprintf(stderr, "Error: Could not set value for line %d.\n", i);
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        printf("Line %d: Value = %d\n", i, value);
    }

    // Release lines on exit (even if terminated by signal)
    atexit([](){
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
    });

    // Keep the program running until interrupted
    while (!terminate) {
        sleep(1);
    }

    printf("\nExiting...\n");

    return EXIT_SUCCESS;
}

