#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 27

// Function prototypes
void cleanup(int signal);
void set_motor_a_pwm(int duty_cycle);
void set_motor_b_pwm(int duty_cycle);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioTerminate();
    exit(0);
}

// Function to set PWM duty cycle for Motor A
void set_motor_a_pwm(int duty_cycle) {
    gpioPWM(MOTOR_A_IN1, duty_cycle);
    gpioPWM(MOTOR_A_IN2, duty_cycle);
}

// Function to set PWM duty cycle for Motor B
void set_motor_b_pwm(int duty_cycle) {
    gpioPWM(MOTOR_B_IN3, duty_cycle);
    gpioPWM(MOTOR_B_IN4, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes as outputs
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_IN1, 255);
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN3, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (program_running) {
        // Example: Move forward at 50% duty cycle
        set_motor_a_pwm(128);
        set_motor_b_pwm(128);
        printf("Motor A: Forward 50%%, Motor B: Forward 50%%\n");

        gpioDelay(2000); // Wait 2 seconds

        // Example: Stop motors
        set_motor_a_pwm(0);
        set_motor_b_pwm(0);
        printf("Motors stopped\n");

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    gpioTerminate();
    return 0;
}

