#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the RGB LED
#define RED_PIN   18
#define GREEN_PIN 23
#define BLUE_PIN  24

// Define the number of cycles and delay
#define CYCLES    3
#define DELAY_MS  5

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

int main()
{
    int i, j;

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    for (i = 0; i < CYCLES && !terminate; ++i)
    {
        // Cycle through colors
        for (j = 0; j < 768 && !terminate; ++j)
        {
            // Calculate color values (HSV to RGB conversion)
            float hue = (float)j / 768.0 * 360.0;
            float h = hue / 60.0;
            int i1 = (int)h;
            float f = h - i1;
            int p = 255 - (int)(255 * f);
            int q = 255 - ((int)(255 * (1 - f)));
            int t = 255 - ((int)(255 * (1 - f)));

            int r, g, b;

            switch (i1)
            {
                case 0:
                    r = 255; g = t; b = p; break;
                case 1:
                    r = q; g = 255; b = p; break;
                case 2:
                    r = p; g = 255; b = t; break;
                case 3:
                    r = p; g = q; b = 255; break;
                case 4:
                    r = t; g = p; b = 255; break;
                default:
                    r = 255; g = p; b = q; break;
            }

            // Set the color values
            gpioPWM(RED_PIN, r);
            gpioPWM(GREEN_PIN, g);
            gpioPWM(BLUE_PIN, b);

            // Delay
            gpioDelay(DELAY_MS * 1000); // Delay in microseconds
        }
    }

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

