#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define MAX_DEVICES 10

// Structure to hold program state
typedef struct {
    int running;
} ProgramState;

ProgramState state = {1}; // Initialize running to 1

// Function to get the list of 1-Wire devices
int get_w1_devices(char *devices[], int max_devices) {
    DIR *dir;
    struct dirent *ent;
    int count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && count < max_devices) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            devices[count++] = strdup(ent->d_name);
        }
    }

    closedir(dir);
    return count;
}

// Function to read the temperature from a DS18B20 sensor
float read_temperature(const char *device_id) {
    char filepath[256];
    snprintf(filepath, sizeof(filepath), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error
    }

    buffer[bytes_read] = '\0';

    // Parse the temperature from the w1_slave file
    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", filepath);
        return -1000.0; // Indicate error
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    return (float)temp_raw / 1000.0;
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting...\n");
        state.running = 0; // Set running to 0 to exit the main loop
    }
}

int main() {
    char *devices[MAX_DEVICES];
    int num_devices;
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Get the list of 1-Wire devices
    num_devices = get_w1_devices(devices, MAX_DEVICES);
    if (num_devices <= 0) {
        fprintf(stderr, "No DS18B20 sensors found. Exiting.\n");
        // Free allocated memory before exiting
        for (i = 0; i < num_devices; i++) {
            free(devices[i]);
        }
        return 1;
    }

    printf("Found %d DS18B20 sensors:\n", num_devices);
    for (i = 0; i < num_devices; i++) {
        printf("  %s\n", devices[i]);
    }

    // Main loop to read temperatures
    for (i = 0; i < 3 && state.running; ++i) {
        for (int j = 0; j < num_devices; j++) {
            float temperature = read_temperature(devices[j]);
            if (temperature > -999.0) { // Check for valid temperature reading
                printf("Sensor %s: Temperature = %.2f °C\n", devices[j], temperature);
            } else {
                fprintf(stderr, "Error reading temperature from sensor %s\n", devices[j]);
            }
        }
        sleep(5);
    }

    // Free allocated memory
    for (i = 0; i < num_devices; i++) {
        free(devices[i]);
    }

    printf("Exiting cleanly.\n");
    return 0;
}

