        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output
    ret = gpiod_line_request_output(line_17, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d as output: %d\n", GPIO_17, ret);
        gpiod_line_release(line_17);
