#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth()
{
    long startTime = 0, endTime = 0;
    int startSec, startUSec, endSec, endUSec;

    // Wait for echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        gpioTime(PI_TIME_RELATIVE, &startSec, &startUSec);
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo start.\n");
        return -1; // Indicate timeout
    }

    startTime = startSec * 1000000 + startUSec;

    // Wait for echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        gpioTime(PI_TIME_RELATIVE, &endSec, &endUSec);
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Timeout waiting for echo end.\n");
        return -1; // Indicate timeout
    }

    endTime = endSec * 1000000 + endUSec;

    return endTime - startTime;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulseWidth)
{
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        triggerSensor();
        long pulseWidth = getPulseWidth();

        if (pulseWidth > 0) // Valid pulse width
        {
            float distance = calculateDistance(pulseWidth);
            if (distance > 0) // Valid distance
            {
                printf("Distance: %.2f cm\n", distance);
            }
            else
            {
                fprintf(stderr, "Invalid distance calculation.\n");
            }
        }
        else
        {
            fprintf(stderr, "Invalid pulse width.\n");
        }

        gpioDelay(100); // 0.1 second delay
    }

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

