#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Function to export the GPIO line
int gpio_export(int pin) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_output(line, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to unexport the GPIO line
void gpio_unexport() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to set the GPIO value
int gpio_set_value(int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    gpio_unexport();
    exit(0);
}

int main() {
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Export the GPIO line
    if (gpio_export(GPIO_PIN) < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Set the GPIO value to 1
        if (gpio_set_value(1) < 0) {
            fprintf(stderr, "Failed to set GPIO high, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Print the current state
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Wait for 5 seconds
        sleep(5);

        // Set the GPIO value to 0
        if (gpio_set_value(0) < 0) {
            fprintf(stderr, "Failed to set GPIO low, retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Print the current state
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Wait for 5 seconds
        sleep(5);
    }

    // This point should not be reached due to the infinite loop
    gpio_unexport();
    return 0;
}

