#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        // Read input values from standard input
        int value1, value2, value3;
        if (scanf("%d,%d,%d", &value1, &value2, &value3) != 3) {
            fprintf(stderr, "Error: Invalid input format. Expected three integers separated by commas.\n");
            continue; // Skip to the next iteration
        }

        // Validate input values
        if (value1 < 0 || value1 > 100 || value2 < 0 || value2 > 100 || value3 < 0 || value3 > 100) {
            fprintf(stderr, "Error: Input values must be between 0 and 100.\n");
            continue; // Skip to the next iteration
        }

        // Apply PWM values
        gpioPWM(PWM_PIN_1, value1 * 255 / 100);
        gpioPWM(PWM_PIN_2, value2 * 255 / 100);
        gpioPWM(PWM_PIN_3, value3 * 255 / 100);

        // Report the state
        printf("PWM1: %d, PWM2: %d, PWM3: %d\n", value1, value2, value3);

        // Delay for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

