#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int read_dht22(float *temperature, float *humidity) {
    int i, j;
    int data[5] = {0, 0, 0, 0, 0};
    unsigned int tick;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - tick > 200) return -1; // Timeout
    }

    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 0) {
        if (gpioTick() - tick > 200) return -1; // Timeout
    }

    tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == 1) {
        if (gpioTick() - tick > 200) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 0) {
            if (gpioTick() - tick > 200) return -1; // Timeout
        }

        tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == 1) {
            if (gpioTick() - tick > 200) return -1; // Timeout
        }

        if ((gpioTick() - tick) > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -1; // Checksum failure
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature *= -1.0;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    for (int i = 0; i < 3; ++i) {
        result = read_dht22(&temperature, &humidity);
        if (result == 0) {
            printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT22 read failed or invalid data received.\n");
        }
        sleep(1);
    }

    gpioTerminate();
    return 0;
}

