void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main()
{
    int i, ret;
    unsigned int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    for (i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            goto cleanup;
        }
    }

    // Request GPIO lines for output
    for (i = 0; i < GPIO_LINES; i++) {
        ret = gpiod_line_request_output(lines[i], "example", 0);
        if (ret < 0) {
            perror("Error requesting GPIO line for output");
            goto cleanup;
        }
    }

    // Main loop
    for (i = 0; !terminate && i < 100; i++) {
        // Set values
        for (value = 0; value <= 1; value++) {
            for (i = 0; i < GPIO_LINES; i++) {
                ret = gpiod_line_set_value(lines[i], value);
                if (ret < 0) {
                    perror("Error setting GPIO line value");
                    goto cleanup;
                }
            }
            printf("Cycle %d: Value %d\n", i + 1, value);
            sleep(0.5);
        }
    }

cleanup:
    // Release GPIO lines
    for (i = 0; i < GPIO_LINES; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return terminate ? EXIT_SUCCESS : EXIT_FAILURE;
}

