// Function to read data from the MAX31855 via SPI
int read_max31855(uint8_t *data)
{
    int result = spiRead(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from MAX31855: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to process the raw data from the MAX31855
int process_data(uint8_t *data, float *thermocouple_temp, float *internal_temp)
{
    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "Thermocouple open circuit.\n");
        return -1;
    } else if (data[3] & 0x02) {
        fprintf(stderr, "Thermocouple shorted to GND.\n");
        return -1;
    } else if (data[3] & 0x04) {
        fprintf(stderr, "Thermocouple shorted to VCC.\n");
        return -1;
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_raw = ((data[0] << 8) | data[1]) >> 2;
    *thermocouple_temp = thermocouple_raw * 0.25;

    // Extract internal temperature (bits 15:4)
    int16_t internal_raw = ((data[2] << 8) | data[3]) >> 4;
    *internal_temp = internal_raw * 0.0625;

    return 0;
}

