#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_ADDR_0x03 0x76
#define BMP280_ADDR_0x77 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_RESET_REG 0xE0
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_TEMP_MSB_REG 0xFA

// Calibration data registers
#define BMP280_CALIB_START 0x88
#define BMP280_CALIB_END   0xA1

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP_X1 0x20
#define BMP280_OVERSAMPLING_PRESS_X1 0x40
#define BMP280_MODE_NORMAL 0x03

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

// Structure to hold calibration data
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib;

// Function prototypes
int bmp280_init(int addr);
int bmp280_read_raw_temperature(int fd, int32_t *raw_temp);
int bmp280_read_raw_pressure(int fd, int32_t *raw_press);
double bmp280_compensate_temperature(int32_t raw_temp);
double bmp280_compensate_pressure(int32_t raw_press, double t_fine);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

// BMP280 initialization function
int bmp280_init(int addr) {
    int fd = i2c_open(addr);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    // Check chip ID
    uint8_t chip_id;
    if (i2c_smbus_read_byte_data(fd, BMP280_CHIP_ID_REG) != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID (expected 0x58, got 0x%02X)\n", chip_id);
        i2c_close(fd);
        return -1;
    }

    // Set oversampling and mode
    uint8_t ctrl_meas = BMP280_OVERSAMPLING_TEMP_X1 | BMP280_OVERSAMPLING_PRESS_X1 | BMP280_MODE_NORMAL;
    if (i2c_smbus_write_byte_data(fd, BMP280_CTRL_MEAS_REG, ctrl_meas) < 0) {
        fprintf(stderr, "Error writing to CTRL_MEAS register: %s\n", strerror(errno));
        i2c_close(fd);
        return -1;
    }

    // Read calibration data
    uint8_t buffer[26];
    if (i2c_smbus_read_i2c_block_data(fd, BMP280_CALIB_START, 26, buffer) != 26) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        i2c_close(fd);
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    i2c_close(fd);
    return 0;
}

// I2C open function
int i2c_open(int addr) {
    const char *i2c_dev = "/dev/i2c-1";
    int fd = open(i2c_dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C close function
void i2c_close(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

// I2C read byte function
int i2c_smbus_read_byte_data(int fd, uint8_t reg) {
    return i2c_smbus_read_byte_data(fd, reg);
}

// I2C write byte function
int i2c_smbus_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    return i2c_smbus_write_byte_data(fd, reg, value);
}

// I2C read block data function
int i2c_smbus_read_i2c_block_data(int fd, uint8_t reg, int length, uint8_t *data) {
    return i2c_smbus_read_i2c_block_data(fd, reg, length, data);
}

// BMP280 read raw temperature function
int bmp280_read_raw_temperature(int fd, int32_t *raw_temp) {
    uint8_t buffer[3];
    if (i2c_smbus_read_i2c_block_data(fd, BMP280_TEMP_MSB_REG, 3, buffer) != 3) {
        fprintf(stderr, "Error reading raw temperature: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    return 0;
}

// BMP280 read raw pressure function
int bmp280_read_raw_pressure(int fd, int32_t *raw_press) {
    uint8_t buffer[3];
    if (i2c_smbus_read_i2c_block_data(fd, BMP280_TEMP_MSB_REG + 3, 3, buffer) != 3) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    *raw_press = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;

    var1 = (((double)raw_temp)/16384.0 - dig_T1/1024.0) * dig_T2;
    var2 = ((((double)raw_temp)/131072.0 - dig_T1/8192.0) * (((double)raw_temp)/131072.0 - dig_T1/8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_press, double t_fine) {
    double var1, var2, p;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;

    var1 = (t_fine/2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2/4.0)+ (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0)*dig_P1;

    if (var1 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }

    p = 1048576.0 - raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize BMP280 sensors
    if (bmp280_init(BMP280_ADDR_0x03) < 0) {
        fprintf(stderr, "Failed to initialize BMP280 sensor at address 0x03\n");
        return 1;
    }
    if (bmp280_init(BMP280_ADDR_0x77) < 0) {
        fprintf(stderr, "Failed to initialize BMP280 sensor at address 0x77\n");
        return 1;
    }

    int32_t raw_temp, raw_press;
    double temp, pressure;

    // Read and print temperature and pressure values
    for (int i = 0; i < 3 && keep_running; ++i) {
        // Sensor 0x03
        if (bmp280_read_raw_temperature(i2c_open(BMP280_ADDR_0x03), &raw_temp) == 0 &&
            bmp280_read_raw_pressure(i2c_open(BMP280_ADDR_0x03), &raw_press) == 0) {
            temp = bmp280_compensate_temperature(raw_temp);
            pressure = bmp280_compensate_pressure(raw_press, temp);
            printf("Sensor 0x03: Temperature: %.2f °C, Pressure: %.2f Pa\n", temp, pressure);
        } else {
            fprintf(stderr, "Error reading from sensor 0x03\n");
        }

        // Sensor 0x77
        if (bmp280_read_raw_temperature(i2c_open(BMP280_ADDR_0x77), &raw_temp) == 0 &&
            bmp280_read_raw_pressure(i2c_open(BMP280_ADDR_0x77), &raw_press) == 0) {
            temp = bmp280_compensate_temperature(raw_temp);
            pressure = bmp280_compensate_pressure(raw_press, temp);
            printf("Sensor 0x77: Temperature: %.2f °C, Pressure: %.2f Pa\n", temp, pressure);
        } else {
            fprintf(stderr, "Error reading from sensor 0x77\n");
        }

        sleep(1);
    }

    // Close I2C devices
    i2c_close(i2c_open(BMP280_ADDR_0x03));
    i2c_close(i2c_open(BMP280_ADDR_0x77));

    return 0;
}

#include <stdio.h>
