#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[4];

// Function prototypes
int setup_gpio(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO function
int setup_gpio(int pin)
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line
    lines[pin] = gpiod_chip_get_line(chip, pin);
    if (!lines[pin]) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line as output
    ret = gpiod_line_request_output(lines[pin], NULL, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void)
{
    int i;
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    int i;
    int value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (setup_gpio(GPIO_17) != 0 ||
        setup_gpio(GPIO_22) != 0 ||
        setup_gpio(GPIO_23) != 0 ||
        setup_gpio(GPIO_24) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        for (i = 0; i < 4; i++) {
            value = (i + 1) % 2; // Toggle between 0 and 1
            if (gpiod_line_set_value(lines[i], value) < 0) {
                perror("Error setting GPIO value");
                cleanup_gpio();
                return 1;
            }
            printf("GPIO %d: %d\n", i + 17, value);
            usleep(500000); // 500ms delay
        }
    }

    return 0;
}

