    uint8_t ctrl_meas = (OVERSAMPLING_TEMP_X1 << 5) | (OVERSAMPLING_PRESSURE_X1 << 2) | MODE_NORMAL;
    if (i2c_write_reg(fd, BME280_CTRL_MEAS_REG, ctrl_meas) < 0) {
