#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// ADXL345 Registers
#define ADXL345_ADDRESS 0x53
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32

int i2c_fd;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure ADXL345: +/- 2g range, full resolution
    uint8_t data_format_value = 0x0B; // 0b00001011
    if (write(i2c_fd, &data_format_value, 1) != 1) {
        perror("Error writing to ADXL345 DATA_FORMAT register");
        close(i2c_fd);
        return 1;
    }

    // Enable measurement mode
    uint8_t power_ctl_value = 0x08; // 0b00001000
    if (write(i2c_fd, &power_ctl_value, 1) != 1) {
        perror("Error writing to ADXL345 POWER_CTL register");
        close(i2c_fd);
        return 1;
    }

    // Read accelerometer data
    int16_t x, y, z;
    uint8_t buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        close(i2c_fd);
        return 1;
    }

    // Combine high and low bytes for each axis
    x = (buffer[1] << 8) | buffer[0];
    y = (buffer[3] << 8) | buffer[2];
    z = (buffer[5] << 8) | buffer[4];

    // Print the readings
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
