#include <gpiod.h>

// Define GPIO pins (BCM numbering)
#define GPIO_4   4
#define GPIO_17  17
#define GPIO_18  18
#define GPIO_22  22
#define GPIO_23  23
#define GPIO_24  24
#define GPIO_25  25
#define GPIO_27  27

// Define GPIO chip name (adjust as needed)
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[8];

// Function prototypes
int setup_gpio(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO line for output
int setup_gpio(int pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (IS_ERR(line)) {
        fprintf(stderr, "Error getting line %d: %ld\n", pin, PTR_ERR(line));
        return -1;
    }

    ret = gpiod_line_request_output(line, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %d\n", pin, ret);
        gpiod_line_release(line);
        return -1;
    }

    lines[pin] = line; // Store the line pointer
    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int i;
    for (i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i;
    unsigned int value;
    struct timespec sleep_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIOCHIP);
        return 1;
    }

    // Initialize GPIO lines
    for (i = 0; i < 8; i++) {
        if (setup_gpio(i) != 0) {
            fprintf(stderr, "Failed to setup GPIO %d\n", i);
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Set values based on index
        for (i = 0; i < 8; i++) {
            value = i % 2; // Toggle between 0 and 1
            if (gpiod_line_set_value(lines[i], value) < 0) {
                fprintf(stderr, "Error setting value for GPIO %d\n", i);
                cleanup_gpio();
                return 1;
            }
        }

        // Print current state
        printf("GPIO State: ");
        for (i = 0; i < 8; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading value for GPIO %d\n", i);
                cleanup_gpio();
                return 1;
            }
            printf("%d ", val);
        }
        printf("\n");

        // Sleep for 50 milliseconds
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0; // This will never be reached due to the infinite loop, but it's good practice
}

