    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;

    // Release lines
    for (int i = 0; i < 8; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

