    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get line %d.\n", i);
            // Release already acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
