#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LED_PIN 27

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO pin configurations
typedef struct {
    int trigger_pin;
    int echo_pin;
    int led_pin;
} gpio_config_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int setup_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);
    gpioSetMode(config->led_pin, PI_OUTPUT);

    gpioWrite(config->trigger_pin, 0); // Ensure trigger is low initially
    gpioWrite(config->led_pin, 0);     // Ensure LED is off initially

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(trigger_pin, 0);
}

// Function to measure the duration of the echo pulse
long measure_pulse_width(int echo_pin) {
    long start_tick, end_tick, diff;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(echo_pin) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(echo_pin) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width_us) {
    if (pulse_width_us <= 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to control the LED based on distance
void control_led(float distance_cm, int led_pin) {
    if (distance_cm > 20.0) {
        gpioWrite(led_pin, 0); // Turn LED off
    } else {
        gpioWrite(led_pin, 1); // Turn LED on
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(ECHO_PIN, 0);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    fprintf(stderr, "GPIO resources released.\n");
}

int main() {
    gpio_config_t config = {TRIGGER_PIN, ECHO_PIN, LED_PIN};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio(&config) != 0) {
        return 1;
    }

    fprintf(stderr, "HC-SR04 Distance Sensor Program\n");

    while (!terminate) {
        trigger_sensor(config.trigger_pin);
        long pulse_width = measure_pulse_width(config.echo_pin);

        if (pulse_width < 0) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            gpioDelay(100); // Small delay before next measurement
            continue;
        }

        float distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Error calculating distance.\n");
            gpioDelay(100); // Small delay before next measurement
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        control_led(distance, config.led_pin);
        gpioDelay(100); // Delay between measurements
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

