#define ECHO_PIN 17

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth()
{
    long startTime = 0, endTime = 0;
    int startSec, startUSec, endSec, endUSec;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0 && !terminate) {
        if (gpioTime(PI_TIME_RELATIVE, &startSec, &startUSec) != 0) {
            fprintf(stderr, "Error getting time: %d\n", gpioTime(PI_TIME_RELATIVE, &startSec, &startUSec));
            return -1; // Indicate error
        }
        startTime = startSec * 1000000 + startUSec;
    }

    if (terminate) return -1;

    // Wait for echo to go low
    while (gpioRead(ECHO_PIN) == 1 && !terminate) {
        if (gpioTime(PI_TIME_RELATIVE, &endSec, &endUSec) != 0) {
            fprintf(stderr, "Error getting time: %d\n", gpioTime(PI_TIME_RELATIVE, &endSec, &endUSec));
            return -1; // Indicate error
        }
        endTime = endSec * 1000000 + endUSec;
    }

    if (terminate) return -1;

    return endTime - startTime;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulseWidth)
{
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (pulseWidth / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        triggerSensor();
        long pulseWidth = getPulseWidth();

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            if (distance >= 0) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error calculating distance\n");
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(100); // 0.1 second delay
    }

    // Clean up and terminate
    gpioTerminate();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 16

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 16 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_GPIO, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_GPIO, 1000);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop: adjust PWM duty cycle
    while (!terminate)
    {
        // Example: Increase duty cycle gradually
        int duty_cycle = 0;
        while (duty_cycle <= 255 && !terminate)
        {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("PWM duty cycle: %d\n", duty_cycle);
            duty_cycle += 10; // Increment by 10 for smoother transition
            gpioDelay(10000);   // Delay for 10ms (adjust as needed)
        }

        // Example: Decrease duty cycle gradually
        while (duty_cycle >= 0 && !terminate)
        {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("PWM duty cycle: %d\n", duty_cycle);
            duty_cycle -= 10; // Decrement by 10 for smoother transition
            gpioDelay(10000);   // Delay for 10ms (adjust as needed)
        }
    }

    // Release GPIO and terminate pigpio
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable register values
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ENABLE_AIEN     (0x10) // RGBC Interrupt Enable

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from the TCS34725
int tcs34725_read_byte(int handle, uint8_t reg)
{
    int result = i2cReadByteData(handle, TCS34725_COMMAND_BIT | reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to the TCS34725
int tcs34725_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, TCS34725_COMMAND_BIT | reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int handle)
{
    // Enable power and RGBC conversion
    if (tcs34725_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        return -1;
    }

    // Set integration time (ATIME).  Atime determines the integration time.
    // Valid values are 2.4ms, 24ms, 50ms, 101ms, 154ms, 256ms, 1000ms, 1200ms
    // We'll use 101ms (0xDB)
    if (tcs34725_write_byte(handle, TCS34725_ATIME, 0xDB) < 0) {
        return -1;
    }

    return 0;
}

// Function to read the RGBC data from the TCS34725
int tcs34725_read_rgbc(int handle, uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear)
{
    int result;

    result = i2cReadWordData(handle, TCS34725_COMMAND_BIT | TCS34725_CDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", result);
        return -1;
    }
    *clear = (uint16_t)result;

    result = i2cReadWordData(handle, TCS34725_COMMAND_BIT | TCS34725_RDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }
    *red = (uint16_t)result;

    result = i2cReadWordData(handle, TCS34725_COMMAND_BIT | TCS34725_GDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading green data: %d\n", result);
        return -1;
    }
    *green = (uint16_t)result;

    result = i2cReadWordData(handle, TCS34725_COMMAND_BIT | TCS34725_BDATA);
    if (result < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", result);
        return -1;
    }
    *blue = (uint16_t)result;

    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t red, green, blue, clear;

    // Main loop
    while (1) {
        if (tcs34725_read_rgbc(i2c_handle, &red, &green, &blue, &clear) == 0) {
            printf("R: %5u G: %5u B: %5u C: %5u\n", red, green, blue, clear);
        } else {
            fprintf(stderr, "Failed to read RGBC data\n");
        }

        gpioDelay(500000); // 0.5 seconds
    }

    // Cleanup (should not reach here in normal execution due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_1 18
#define GPIO_PIN_2 23

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_1 = NULL;
static struct gpiod_line *line_2 = NULL;

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");

    if (line_1) {
        gpiod_line_set_value(line_1, 0);
        gpiod_line_release(line_1);
    }
    if (line_2) {
        gpiod_line_set_value(line_2, 0);
        gpiod_line_release(line_2);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    unsigned int value;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    line_1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line_1) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_1);
        gpiod_chip_close(chip);
        return 1;
    }

    line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line_2) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_2);
        gpiod_line_release(line_1);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_1, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %d\n", GPIO_PIN_1, ret);
        gpiod_line_release(line_1);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_2, "myapp", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %d\n", GPIO_PIN_2, ret);
        gpiod_line_release(line_1);
        gpiod_line_release(line_2);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        value = gpiod_line_get_value(line_1);
        if (value >= 0) {
            printf("GPIO %d: %d\n", GPIO_PIN_1, value);
        } else {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN_1, value);
        }

        value = gpiod_line_get_value(line_2);
        if (value >= 0) {
            printf("GPIO %d: %d\n", GPIO_PIN_2, value);
        } else {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN_2, value);
        }

        usleep(10000); // 0.01 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins (BCM numbering)
#define GPIO_4   4
#define GPIO_17  17
#define GPIO_18  18
#define GPIO_22  22
#define GPIO_23  23
#define GPIO_24  24
#define GPIO_27  27

// Structure to hold GPIO chip and line information
struct gpio_config {
    struct gpiod_chip *chip;
    struct gpiod_line *line[7];
};

// Global variable to store the GPIO configuration
struct gpio_config config;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int setup_gpio(struct gpio_config *config);

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpio_config *config);

// Function to set GPIO value
int set_gpio_value(struct gpio_config *config, int pin, int value);

// Function to get GPIO value
int get_gpio_value(struct gpio_config *config, int pin);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO configuration
    config.chip = NULL;
    for (int i = 0; i < 7; i++) {
        config.line[i] = NULL;
    }

    // Setup GPIO pins
    if (setup_gpio(&config) != 0) {
        fprintf(stderr, "Failed to setup GPIO pins.\n");
        return 1;
    }

    // Main loop: Toggle GPIO values
    while (1) {
        for (int i = 0; i < 7; i++) {
            int current_value = get_gpio_value(&config, i);
            if (set_gpio_value(&config, i, !current_value) != 0) {
                fprintf(stderr, "Failed to set GPIO %d value.\n", i);
                break; // Exit loop if setting value fails
            }
        }
        usleep(500000); // Delay for 0.5 seconds
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio(&config);
    exit(0);
}

// Function to initialize GPIO lines
int setup_gpio(struct gpio_config *config) {
    // Open GPIO chip
    config->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!config->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line handles for each pin
    config->line[0] = gpiod_chip_get_line(config->chip, GPIO_4);
    config->line[1] = gpiod_chip_get_line(config->chip, GPIO_17);
    config->line[2] = gpiod_chip_get_line(config->chip, GPIO_18);
    config->line[3] = gpiod_chip_get_line(config->chip, GPIO_22);
    config->line[4] = gpiod_chip_get_line(config->chip, GPIO_23);
    config->line[5] = gpiod_chip_get_line(config->chip, GPIO_24);
    config->line[6] = gpiod_chip_get_line(config->chip, GPIO_27);

    if (!config->line[0] || !config->line[1] || !config->line[2] ||
        !config->line[3] || !config->line[4] || !config->line[5] || !config->line[6]) {
        perror("Error getting GPIO line");
        cleanup_gpio(config);
        return -1;
    }

    // Request line as output with initial value low
    struct gpiod_line_request_config req_config;
    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer = "example";
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req_config.flags = 0; // No flags needed for output

    for (int i = 0; i < 7; i++) {
        if (gpiod_line_request(config->line[i], &req_config, 0) != 0) {
            perror("Error requesting GPIO line as output");
            cleanup_gpio(config);
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpio_config *config) {
    // Release line requests
    for (int i = 0; i < 7; i++) {
        if (config->line[i]) {
            gpiod_line_release(config->line[i]);
        }
    }

    // Close GPIO chip
    if (config->chip) {
        gpiod_chip_close(config->chip);
    }
}

// Function to set GPIO value
int set_gpio_value(struct gpio_config *config, int pin, int value) {
    if (pin < 0 || pin > 6) {
        fprintf(stderr, "Invalid GPIO pin number: %d\n", pin);
        return -1;
    }

    if (gpiod_line_set_value(config->line[pin], value) != 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to get GPIO value
int get_gpio_value(struct gpio_config *config, int pin) {
    if (pin < 0 || pin > 6) {
        fprintf(stderr, "Invalid GPIO pin number: %d\n", pin);
        return -1;
    }

    int value = gpiod_line_get_value(config->line[pin]);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

