#define GPIO_24 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line_22 = NULL;
static struct gpiod_line *line_24 = NULL;

void cleanup(int signum) {
    printf("\nCleaning up and exiting...\n");

    if (line_22) {
        gpiod_line_set_value(line_22, 0);
        gpiod_line_release(line_22);
    }
    if (line_24) {
        gpiod_line_set_value(line_24, 0);
        gpiod_line_release(line_24);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    unsigned int value_22, value_24;

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line for GPIO 22
    line_22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line_22) {
        perror("Error getting line for GPIO 22");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get line for GPIO 24
    line_24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line_24) {
        perror("Error getting line for GPIO 24");
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for output
    ret = gpiod_line_request_output(line_22, "myapp", 0);
    if (ret < 0) {
        perror("Error requesting line 22 as output");
        gpiod_line_release(line_22);
        gpiod_line_release(line_24);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_24, "myapp", 0);
    if (ret < 0) {
        perror("Error requesting line 24 as output");
        gpiod_line_release(line_22);
        gpiod_line_release(line_24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 22
        value_22 = !value_22;
        ret = gpiod_line_set_value(line_22, value_22);
        if (ret < 0) {
            perror("Error setting value on line 22");
            cleanup(0);
        }

        // Toggle GPIO 24
        value_24 = !value_24;
        ret = gpiod_line_set_value(line_24, value_24);
        if (ret < 0) {
            perror("Error setting value on line 24");
            cleanup(0);
        }

        // Print current state
        printf("GPIO 22: %d, GPIO 24: %d\n", value_22, value_24);

        usleep(10000); // 0.01 seconds
    }

    return 0; // This will never be reached due to the infinite loop, but it's good practice
}

