#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig)
{
    fprintf(stderr, "\nSignal caught, exiting gracefully.\n");
    terminate = 1;
}

int main()
{
    int status;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle for each pin
        gpioPWM(PWM_PIN_1, 128); // 50% duty cycle
        gpioPWM(PWM_PIN_2, 64);  // 25% duty cycle
        gpioPWM(PWM_PIN_3, 192); // 75% duty cycle

        // Print current PWM settings
        printf("PWM_PIN_1: 50%%, PWM_PIN_2: 25%%, PWM_PIN_3: 75%%\n");

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

