#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define UART_PORT "/dev/ttyAMA0"
#define BAUD_RATE B9600

volatile sig_atomic_t keep_running = 1;
int uart_fd = -1;

void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int setup_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;             /* mask the character size bits */
    tty.c_cflag |= CS8;              /* 8-bit characters */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity bit */
    tty.c_cflag &= ~CSTOPB;            /* only need 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;           /* disable hardware flow control */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;      // read doesn't block
    tty.c_cc[VTIME] = 5;     // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("UART initialized. Reading from %s at %d baud.\n", UART_PORT, B9600);

    while (keep_running) {
        unsigned char buffer[256];
        ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s", buffer);
        } else if (bytes_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("Error reading from UART");
            break;
        }

        usleep(100000); // 0.1 seconds
    }

    close(uart_fd);
    printf("UART closed. Exiting.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_PIN_3 3
#define GPIO_PIN_5 5

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line3, *line5;

// Function prototypes
int setup_gpio(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Setup GPIO function
int setup_gpio(int pin)
{
    int ret;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line
    line3 = gpiod_chip_get_line(chip, pin);
    if (!line3) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "example";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line3, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void)
{
    int ret;

    // Release line 3
    ret = gpiod_line_release(line3);
    if (ret < 0) {
        perror("Error releasing GPIO line 3");
    }

    // Release line 5
    ret = gpiod_line_release(line5);
    if (ret < 0) {
        perror("Error releasing GPIO line 5");
    }

    // Close chip
