#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int setup_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(config->trigger_pin, 0);
    gpioDelay(1000); // 1ms delay

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the duration of the echo pulse
long measure_pulse_width() {
    long start_tick, end_tick, diff;

    // Wait for echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Indicate timeout
    }
    start_tick = gpioTick();

    // Wait for echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1; // Indicate timeout
    }
    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width_us) {
    if (pulse_width_us < 0) return -1.0; // Indicate error
    return (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to report the distance
void report_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    fprintf(stderr, "GPIO terminated.\n");
}

int main() {
    gpio_config_t config = {TRIGGER_PIN, ECHO_PIN};

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio(&config) != 0) {
        return 1;
    }

    fprintf(stderr, "HC-SR04 sensor interface started.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance >= 0) {
                report_distance(distance);
            } else {
                fprintf(stderr, "Error calculating distance\n");
            }
        } else {
            fprintf(stderr, "Error measuring pulse width\n");
        }

        gpioDelay(100000); // Delay 100ms between measurements
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

